-- DSR originals are captured candidates, never automatically classified personal or disclosed.
-- File review is separate from antivirus and from the response's independent publication.
create table public.dsr_redacted_file_uploads_v1(
 id uuid primary key default extensions.gen_random_uuid(),request_id uuid not null references public.data_subject_requests(id),organization_id uuid not null references public.organizations(id),actor_user_id uuid not null references auth.users(id),version integer not null check(version>0),storage_bucket text not null default 'privacy-response-files'check(storage_bucket='privacy-response-files'),storage_path text not null unique,file_name text not null check(length(file_name)between 1 and 255),mime_type text not null check(mime_type in('application/pdf','image/jpeg','image/png','text/plain','application/json','text/csv','application/zip')),size_bytes bigint not null check(size_bytes between 1 and 10485760),expected_sha256 text not null check(expected_sha256~'^[a-f0-9]{64}$'),status text not null default 'RESERVED'check(status in('RESERVED','UPLOADED','CANCELLED')),scan_status text not null default 'PENDING'check(scan_status in('PENDING','CLEAN','REJECTED','ERROR')),scan_result_id uuid,storage_object_id uuid,detected_mime_type text,idempotency_key uuid not null,created_at timestamptz not null default clock_timestamp(),expires_at timestamptz not null default clock_timestamp()+interval'24 hours',unique(actor_user_id,idempotency_key),unique(request_id,version)
);
alter table public.dsr_redacted_file_uploads_v1 enable row level security;
revoke all on public.dsr_redacted_file_uploads_v1 from public,anon,authenticated,service_role;
create function private.dsr_file_source_identity_hash_v1(p_row jsonb)returns text language sql immutable set search_path=pg_catalog,private set timezone='UTC' as $$select private.canonical_request_hash(p_row-array['status','scan_status','scan_result_id','current_scan_result_id','scanned_at','reviewed_at','reviewed_by','row_version','updated_at','detected_mime_type','detected_size_bytes','rejection_reason_public','storage_object_id'])$$;
create function private.dsr_file_candidate_v1(p_type text,p_id text,p_row jsonb,p_bucket text,p_path text,p_sha text,p_size bigint,p_mime text,p_name text,p_trust_kind text)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$declare object storage.objects%rowtype;begin
 if p_bucket is not null and p_path is not null then select*into object from storage.objects where bucket_id=p_bucket and name=p_path;end if;
 return jsonb_build_object('id',private.canonical_request_hash(jsonb_build_object('type',p_type,'id',p_id)),'source_type',p_type,'source_id',p_id,'source_hash',private.canonical_request_hash(p_row),'source_identity_hash',private.dsr_file_source_identity_hash_v1(p_row),'bucket',p_bucket,'path',p_path,'sha256',p_sha,'size_bytes',coalesce(p_size,case when object.metadata->>'size'~'^[0-9]{1,15}$'then(object.metadata->>'size')::bigint end)::text,'mime_type',coalesce(p_mime,object.metadata->>'mimetype'),'file_name',coalesce(nullif(p_name,''),p_type||'-'||p_id),'storage_object_id',object.id,'trust_kind',p_trust_kind,'personal_data_review_required',true,'third_party_review_required',true);
end$$;
create function private.dsr_all_collect_file_sources_v1(p_request_id uuid)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$
declare d public.data_subject_requests%rowtype;subject_user uuid;spec record;entries jsonb:='[]';part jsonb;unknown jsonb;avatar text;begin
 select*into d from public.data_subject_requests where id=p_request_id;subject_user:=private.dsr_account_subject_v1(d.id);
 if d.id is null or d.verified_at is null or d.request_type not in('ACCESS','PORTABILITY')or subject_user is null then raise exception'DSR_VERIFIED_SUBJECT_REQUIRED'using errcode='42501';end if;
 for spec in select*from(values
('public.client_compliance_documents','public.client_compliance_documents r','r.organization_id=$1','r.id::text','r.storage_bucket','r.storage_object_path','r.declared_sha256','r.declared_size_bytes','r.detected_mime_type','r.original_file_name','CLIENT_DOCUMENT'),
('public.provider_document_versions','public.provider_document_versions r','r.provider_organization_id=$1','r.id::text','''provider-qualification''','r.storage_object_path','r.content_hash','null','null','null','PROVIDER_DOCUMENT'),
('public.provider_document_upload_reservations','public.provider_document_upload_reservations r','r.provider_organization_id=$1','r.id::text','r.storage_bucket','r.storage_object_path','null','r.declared_size_bytes','r.declared_mime_type','null','UNTRUSTED'),
('public.provider_document_scan_jobs','public.provider_document_scan_jobs r','r.provider_organization_id=$1','r.id::text','r.storage_bucket','r.storage_object_path','r.declared_sha256','null','r.declared_mime_type','null','PROVIDER_SCAN_JOB'),
('public.provider_payment_proof_uploads','public.provider_payment_proof_uploads r','r.provider_organization_id=$1','r.id::text','r.storage_bucket','r.storage_object_path','r.declared_sha256','r.declared_size_bytes','r.declared_mime_type','r.original_file_name','PAYMENT_UPLOAD'),
('public.provider_payment_proofs','public.provider_payment_proofs r','r.provider_organization_id=$1','r.id::text','r.storage_bucket','r.storage_object_path','r.sha256','r.size_bytes','r.mime_type','r.original_file_name','PAYMENT_PROOF'),
('public.provider_payable_event_proofs','public.provider_payable_event_proofs r','r.provider_organization_id=$1','r.id::text','r.storage_bucket','r.storage_object_path','r.sha256','r.size_bytes','r.mime_type','r.original_file_name','PAYABLE_PROOF'),
('public.delivery_proofs','public.delivery_proofs r join public.delivery_versions v on v.id=r.delivery_version_id join public.deliverables dv on dv.id=v.deliverable_id join public.missions m on m.id=dv.mission_id','($1 in(m.client_organization_id,m.provider_organization_id))','r.id::text','r.storage_bucket','r.storage_path','r.evidence_hash','null','null','null','DELIVERY_PROOF'),
('public.internal_message_attachment_uploads','public.internal_message_attachment_uploads r join public.internal_message_drafts dr on dr.id=r.draft_id','dr.sender_organization_id=$1','r.id::text','r.storage_bucket','r.storage_path','r.expected_sha256','r.size_bytes','r.media_type','r.original_file_name','MESSAGE_UPLOAD'),
('public.internal_message_attachments','public.internal_message_attachments r join public.internal_messages m on m.id=r.message_id','m.sender_organization_id=$1','r.id::text','r.storage_bucket','r.storage_object_path','r.sha256','r.size_bytes','r.mime_type','r.original_file_name','MESSAGE_ATTACHMENT'),
('public.provider_billing_document_artifacts','public.provider_billing_document_artifacts r','r.provider_organization_id=$1','r.id::text','''provider-billing''','r.storage_path','r.pdf_sha256','null','''application/pdf''','null','PROVIDER_PDF'),
('public.client_commercial_document_artifacts','public.client_commercial_document_artifacts r join public.client_commercial_documents doc on doc.id=r.document_id','doc.organization_id=$1','r.document_id::text||'':''||r.locale','''client-billing-documents''','r.storage_path','r.pdf_sha256','r.size_bytes','''application/pdf''','null','CLIENT_PDF'),
('private.contract_signature_source_artifacts_v1','private.contract_signature_source_artifacts_v1 r join public.contract_versions v on v.id=r.contract_version_id join public.contracts c on c.id=v.contract_id','$1 in(c.client_organization_id,c.provider_organization_id)','r.id::text','''signature-source-documents''','r.storage_path','r.pdf_sha256','r.size_bytes','''application/pdf''','null','CONTRACT_PDF'),
('public.signature_documents','public.signature_documents r join public.contract_versions v on v.id=r.contract_version_id join public.contracts c on c.id=v.contract_id','$1 in(c.client_organization_id,c.provider_organization_id)','r.id::text','''signature-source-documents''','r.storage_path','r.sha256','null','r.mime_type','r.file_name','SIGNATURE_DOCUMENT'),
('public.signature_signer_authorities','public.signature_signer_authorities r','r.organization_id=$1','r.id::text','null','r.evidence_storage_path','r.evidence_sha256','null','null','null','UNTRUSTED'),
('public.dispute_evidence','public.dispute_evidence r join public.dispute_cases c on c.id=r.dispute_case_id','$1 in(c.client_organization_id,c.provider_organization_id)','r.id::text','null','r.storage_path','r.evidence_hash','null','null','null','UNTRUSTED'),
('public.brand_assets','public.brand_assets r','r.organization_id=$1','r.id::text','null','r.storage_path','r.content_hash','null','null','null','UNTRUSTED'),
('public.social_media_assets','public.social_media_assets r','r.organization_id=$1','r.id::text','null','r.storage_path','r.sha256','r.byte_length','r.media_type','null','UNTRUSTED'),
('public.organization_export_artifacts','public.organization_export_artifacts r','r.organization_id=$1','r.id::text','null','r.storage_reference','r.sha256','r.size_bytes','null','null','UNTRUSTED'),
('public.privacy_notices','public.privacy_notices r','r.organization_id=$1','r.id::text','null','r.storage_reference','r.content_hash','null','null','null','UNTRUSTED'),
('public.data_subject_requests','public.data_subject_requests r','r.organization_id=$1 and r.subject_reference_hash=(select subject_reference_hash from public.data_subject_requests where id=$3)','r.id::text','null','r.export_storage_reference','null','null','null','null','UNTRUSTED'),
('public.admin_external_validation_evidence_versions','public.admin_external_validation_evidence_versions r','r.submitted_by=$2','r.id::text','null','r.storage_reference','r.evidence_sha256','null','null','null','UNTRUSTED'),
('private.signature_native_cancellation_attestations_v1','private.signature_native_cancellation_attestations_v1 r join public.signature_envelopes e on e.id=r.envelope_id join public.contracts c on c.id=e.contract_id join storage.objects obj on obj.id=r.storage_object_id','$1 in(c.client_organization_id,c.provider_organization_id)','r.envelope_id::text','obj.bucket_id','obj.name','r.certificate_sha256','null','null','null','UNTRUSTED'),
('private.franchise_mandate_signature_proofs_v1:pdf','private.franchise_mandate_signature_proofs_v1 r join storage.objects obj on obj.id=r.pdf_storage_object_id','$1 in(r.issuer_organization_id,r.operator_organization_id)','r.id::text','obj.bucket_id','obj.name','r.pdf_sha256','null','null','null','UNTRUSTED'),
('private.franchise_mandate_signature_proofs_v1:evidence','private.franchise_mandate_signature_proofs_v1 r join storage.objects obj on obj.id=r.evidence_storage_object_id','$1 in(r.issuer_organization_id,r.operator_organization_id)','r.id::text','obj.bucket_id','obj.name','null','null','null','null','UNTRUSTED'),
('public.dsr_redacted_file_uploads_v1','public.dsr_redacted_file_uploads_v1 r join public.data_subject_requests req on req.id=r.request_id','r.organization_id=$1 and req.subject_reference_hash=(select subject_reference_hash from public.data_subject_requests where id=$3)','r.id::text','r.storage_bucket','r.storage_path','r.expected_sha256','r.size_bytes','r.mime_type','r.file_name','DSR_REDACTED'))registry(source_type,from_sql,scope_sql,id_sql,bucket_sql,path_sql,sha_sql,size_sql,mime_sql,name_sql,trust_kind)loop
  execute format('select coalesce(jsonb_agg(private.dsr_file_candidate_v1(%L,%s,to_jsonb(r),%s,%s,%s,%s,%s,%s,%L)order by %s),''[]''::jsonb)from %s where(%s)and(%s)is not null',spec.source_type,spec.id_sql,spec.bucket_sql,spec.path_sql,spec.sha_sql,spec.size_sql,spec.mime_sql,spec.name_sql,spec.trust_kind,spec.id_sql,spec.from_sql,spec.scope_sql,spec.path_sql)into part using d.organization_id,subject_user,d.id;
  entries:=entries||part;
 end loop;
 -- Earlier private JSON responses are actual files owned by this subject, not just metadata.
 select coalesce(jsonb_agg(private.dsr_file_candidate_v1('public.dsr_private_responses_v1',r.id::text,to_jsonb(r),null,r.id::text,r.sha256,octet_length(r.response_json)::bigint,'application/json','privacy-response-'||r.id::text||'.json','INLINE_DSR_RESPONSE')order by r.id),'[]')into part from public.dsr_private_responses_v1 r join public.data_subject_requests request on request.id=r.request_id where request.organization_id=d.organization_id and r.subject_user_id=subject_user;
 entries:=entries||part;
 -- Unbound delivery uploads remain personal-file candidates when their actual
 -- owner and deliverable both establish this subject/organization scope.
 select coalesce(jsonb_agg(private.dsr_file_candidate_v1('storage.delivery_orphan',o.id::text,to_jsonb(o),o.bucket_id,o.name,null,null,null,'Unbound personal delivery upload','UNTRUSTED')order by o.id),'[]')into part from storage.objects o join public.deliverables deliverable on deliverable.id::text=split_part(o.name,'/',2)join public.missions mission on mission.id=deliverable.mission_id where o.bucket_id='delivery-proofs'and o.owner_id=subject_user::text and split_part(o.name,'/',1)=subject_user::text and d.organization_id in(mission.client_organization_id,mission.provider_organization_id)and not exists(select 1 from public.delivery_proofs proof where proof.storage_bucket=o.bucket_id and proof.storage_path=o.name);
 entries:=entries||part;
 -- A reservation, scan projection and reviewed document may reference the same
 -- physical object. Keep one byte-delivery slot with its complete captured lineage.
 with original as(select entry,coalesce(entry->>'storage_object_id',entry->>'id')physical from jsonb_array_elements(entries)entry),ranked as(select*,row_number()over(partition by physical order by case entry->>'trust_kind'when'PROVIDER_DOCUMENT'then 1 when'PAYMENT_PROOF'then 1 when'PAYABLE_PROOF'then 1 when'MESSAGE_ATTACHMENT'then 1 when'UNTRUSTED'then 9 else 2 end,entry->>'id')priority from original),grouped as(select physical,jsonb_agg(jsonb_build_object('source_type',entry->>'source_type','source_id',entry->>'source_id','source_hash',entry->>'source_hash')order by entry->>'id')aliases from original group by physical)
 select coalesce(jsonb_agg(r.entry||jsonb_build_object('id',private.canonical_request_hash(jsonb_build_object('physical_source',r.physical)),'primary_source_hash',r.entry->>'source_hash','source_aliases',g.aliases,'source_hash',private.canonical_request_hash(jsonb_build_object('primary_source_hash',r.entry->>'source_hash','aliases',g.aliases)))order by r.physical),'[]')into entries from ranked r join grouped g using(physical)where r.priority=1;
 -- Account avatar references are candidates only for the verified subject.
 select coalesce(nullif(raw_user_meta_data->>'avatar_url',''),nullif(raw_user_meta_data->>'picture',''))into avatar from auth.users where id=subject_user;
 if avatar is not null then entries:=entries||jsonb_build_array(private.dsr_file_candidate_v1('auth.users.avatar',subject_user::text,jsonb_build_object('user_id',subject_user,'avatar_reference_hash',private.canonical_request_hash(to_jsonb(avatar))),null,avatar,null,null,null,'Account avatar reference','UNTRUSTED'));end if;
 -- New Storage reference families must be added explicitly before claiming complete coverage.
 select coalesce(jsonb_agg(family order by family),'[]')into unknown from(select distinct c.table_schema||'.'||c.table_name family from information_schema.columns c where c.table_schema in('public','private')and c.column_name in('storage_path','storage_object_path','storage_reference','export_storage_reference','evidence_storage_path','storage_object_id','pdf_storage_object_id','evidence_storage_object_id')and c.data_type in('text','uuid')and c.table_name not in('provider_document_scan_jobs')and(c.table_schema||'.'||c.table_name)<>all(array[
'private.contract_signature_source_artifacts_v1','private.franchise_mandate_signature_proofs_v1','private.signature_native_cancellation_attestations_v1','public.admin_external_validation_evidence_versions','public.brand_assets','public.client_commercial_document_artifacts','public.client_compliance_documents','public.data_subject_requests','public.delivery_proofs','public.dispute_evidence','public.dsr_redacted_file_uploads_v1','public.internal_message_attachment_uploads','public.internal_message_attachments','public.organization_export_artifacts','public.privacy_notices','public.provider_billing_document_artifacts','public.provider_document_scan_jobs','public.provider_document_upload_reservations','public.provider_document_versions','public.provider_payable_event_proofs','public.provider_payment_proof_uploads','public.provider_payment_proofs','public.signature_documents','public.signature_signer_authorities','public.social_media_assets']))families;
 if jsonb_array_length(entries)>10000 or octet_length(entries::text)>12582912 then raise exception'DSR_FILE_CAPTURE_TOO_LARGE'using errcode='54000';end if;
 return jsonb_build_object('collector_version',1,'entries',entries,'hash',private.canonical_request_hash(entries),'coverage_complete',jsonb_array_length(unknown)=0,'uncovered_families',unknown);
end$$;
revoke all on function private.dsr_file_candidate_v1(text,text,jsonb,text,text,text,bigint,text,text,text),private.dsr_all_collect_file_sources_v1(uuid)from public,anon,authenticated,service_role;

create table private.dsr_file_transfer_tickets_v1(id uuid primary key default extensions.gen_random_uuid(),kind text not null check(kind in('UPLOAD_COMMIT','SOURCE_REVIEW','REDACTED_REVIEW','RESPONSE_FILE')),actor_user_id uuid not null references auth.users(id),session_id uuid default nullif(auth.jwt()->>'session_id','')::uuid,maintenance_actor boolean not null default(session_user in('postgres','supabase_admin')),request_id uuid not null references public.data_subject_requests(id),package_id uuid,entry_id text,response_id uuid,source_hash text,payload jsonb not null,expires_at timestamptz not null default clock_timestamp()+interval'3 minutes',created_at timestamptz not null default clock_timestamp());
create table private.dsr_file_transfer_completions_v1(ticket_id uuid primary key references private.dsr_file_transfer_tickets_v1(id),request_hash text not null check(request_hash~'^[a-f0-9]{64}$'),sha256 text not null check(sha256~'^[a-f0-9]{64}$'),size_bytes bigint not null check(size_bytes>0),completed_at timestamptz not null default clock_timestamp());
create table private.dsr_redacted_file_scan_claims_v1(upload_id uuid primary key references public.dsr_redacted_file_uploads_v1(id),worker_id uuid not null,lease_token uuid not null,leased_until timestamptz not null,attempt_count integer not null default 0,row_version integer not null default 1 check(row_version>0));
create table private.dsr_redacted_file_scan_results_v1(id uuid primary key default extensions.gen_random_uuid(),upload_id uuid not null references public.dsr_redacted_file_uploads_v1(id),sequence integer not null check(sequence>0),result text not null check(result in('CLEAN','INFECTED','ERROR')),computed_sha256 text,engine_code text not null,engine_version text not null,idempotency_key text not null,request_hash text not null,correlation_id uuid not null,recorded_at timestamptz not null default clock_timestamp(),unique(upload_id,sequence),unique(upload_id,idempotency_key));
create table private.dsr_redacted_file_scan_retries_v1(id uuid primary key default extensions.gen_random_uuid(),upload_id uuid not null references public.dsr_redacted_file_uploads_v1(id),attempt integer not null,failure_code text not null,computed_sha256 text,retry_after timestamptz,recorded_at timestamptz not null default clock_timestamp());
do $$declare name text;begin foreach name in array array['dsr_file_transfer_tickets_v1','dsr_file_transfer_completions_v1','dsr_redacted_file_scan_claims_v1','dsr_redacted_file_scan_results_v1','dsr_redacted_file_scan_retries_v1']loop execute format('alter table private.%I enable row level security',name);execute format('revoke all on private.%I from public,anon,authenticated,service_role',name);if name<>'dsr_redacted_file_scan_claims_v1'then execute format('create trigger %I before update or delete on private.%I for each row execute function private.prevent_update_delete()',left(name,43)||'_immutable',name);end if;end loop;end$$;
create function private.dsr_verified_file_request_v1(p_request_id uuid,p_require_open boolean)returns public.data_subject_requests language plpgsql stable security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$declare d public.data_subject_requests%rowtype;begin
 select*into d from public.data_subject_requests where id=p_request_id;
 if not coalesce(private.dsr_response_staff_v1(),false)then raise exception'DSR_RESPONSE_STAFF_REQUIRED'using errcode='42501';end if;
 if d.id is null or d.verified_at is null or d.request_type not in('ACCESS','PORTABILITY')or private.dsr_account_subject_v1(d.id)is null then raise exception'DSR_VERIFIED_SUBJECT_REQUIRED'using errcode='42501';end if;
 if p_require_open is distinct from false and d.status<>'IN_REVIEW'then raise exception'DSR_FILE_REVIEW_NOT_OPEN'using errcode='55000';end if;return d;
end$$;
create table private.dsr_file_scan_reset_capabilities_v1(transaction_id bigint not null,upload_id uuid not null,actor_user_id uuid not null,expected_result_id uuid not null,primary key(transaction_id,upload_id));
alter table private.dsr_file_scan_reset_capabilities_v1 enable row level security;
revoke all on private.dsr_file_scan_reset_capabilities_v1 from public,anon,authenticated,service_role;
create function private.guard_dsr_redacted_file_upload_v1()returns trigger language plpgsql set search_path=pg_catalog,private set timezone='UTC' as $$begin
 if tg_op='DELETE'or(to_jsonb(new)-array['status','scan_status','scan_result_id','storage_object_id','detected_mime_type'])is distinct from(to_jsonb(old)-array['status','scan_status','scan_result_id','storage_object_id','detected_mime_type'])then raise exception'DSR_FILE_VERSION_IMMUTABLE'using errcode='55000';end if;
 if auth.role()is distinct from'service_role'and(new.scan_status is distinct from old.scan_status or new.scan_result_id is distinct from old.scan_result_id or new.storage_object_id is distinct from old.storage_object_id or new.detected_mime_type is distinct from old.detected_mime_type)and not(old.scan_status='ERROR'and new.scan_status='PENDING'and new.scan_result_id is null and new.storage_object_id is not distinct from old.storage_object_id and new.detected_mime_type is not distinct from old.detected_mime_type and exists(select 1 from private.dsr_file_scan_reset_capabilities_v1 cap where cap.transaction_id=txid_current()and cap.upload_id=old.id and cap.actor_user_id=auth.uid()and cap.expected_result_id=old.scan_result_id))then raise exception'DSR_TRUSTED_FILE_PROCESSOR_REQUIRED'using errcode='42501';end if;
 if new.status is distinct from old.status and not((old.status in('RESERVED','CANCELLED')and new.status='UPLOADED'and auth.role()='service_role')or(old.status in('RESERVED','UPLOADED')and new.status='CANCELLED'))then raise exception'DSR_FILE_VERSION_IMMUTABLE'using errcode='55000';end if;return new;
end$$;
create trigger dsr_redacted_file_upload_guard before update or delete on public.dsr_redacted_file_uploads_v1 for each row execute function private.guard_dsr_redacted_file_upload_v1();
create function public.reserve_dsr_redacted_file_v1(p_request_id uuid,p_file_name text,p_mime_type text,p_size_bytes bigint,p_sha256 text,p_idempotency_key uuid)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$declare d public.data_subject_requests%rowtype;u public.dsr_redacted_file_uploads_v1%rowtype;uid uuid:=extensions.gen_random_uuid();v integer;begin
 d:=private.dsr_verified_file_request_v1(p_request_id,true);
 if p_idempotency_key is null or length(coalesce(p_file_name,''))not between 1 and 255 or p_file_name~'[[:cntrl:]/\\]'or p_size_bytes is null or p_size_bytes not between 1 and 10485760 or p_sha256 is null or p_sha256!~'^[a-f0-9]{64}$'or p_mime_type is null or p_mime_type not in('application/pdf','image/jpeg','image/png','text/plain','application/json','text/csv','application/zip')then raise exception'INVALID_DSR_FILE_UPLOAD'using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('dsr-file-upload-key:'||auth.uid()::text||':'||p_idempotency_key::text,0));
 select*into u from public.dsr_redacted_file_uploads_v1 where actor_user_id=auth.uid()and idempotency_key=p_idempotency_key;
 if found then if u.request_id is distinct from d.id or u.file_name is distinct from p_file_name or u.mime_type is distinct from p_mime_type or u.size_bytes is distinct from p_size_bytes or u.expected_sha256 is distinct from p_sha256 then raise exception'IDEMPOTENCY_PAYLOAD_MISMATCH'using errcode='22000';end if;
 else
  perform pg_advisory_xact_lock(hashtextextended('dsr-file-upload:'||d.id::text,0));select coalesce(max(version),0)+1 into v from public.dsr_redacted_file_uploads_v1 where request_id=d.id;
  insert into public.dsr_redacted_file_uploads_v1(id,request_id,organization_id,actor_user_id,version,storage_path,file_name,mime_type,size_bytes,expected_sha256,idempotency_key)values(uid,d.id,d.organization_id,auth.uid(),v,'dsr-files/'||d.id::text||'/'||uid::text,p_file_name,p_mime_type,p_size_bytes,p_sha256,p_idempotency_key)returning*into u;
 end if;
 return jsonb_build_object('upload_id',u.id,'version',u.version,'bucket',u.storage_bucket,'path',u.storage_path,'status',u.status,'scan_status',u.scan_status,'expires_at',u.expires_at);
end$$;
create index dsr_file_transfer_actor_recent_idx on private.dsr_file_transfer_tickets_v1(actor_user_id,created_at);
create function private.dsr_file_transfer_rate_limit_v1()returns void language plpgsql security definer set search_path=pg_catalog,private set timezone='UTC' as $$begin
 perform pg_advisory_xact_lock(hashtextextended('dsr-file-transfer:'||auth.uid()::text,0));
 if(select count(*)from private.dsr_file_transfer_tickets_v1 where actor_user_id=auth.uid()and created_at>clock_timestamp()-interval'1 minute')>=60 or(select count(*)from private.dsr_file_transfer_tickets_v1 t where actor_user_id=auth.uid()and expires_at>clock_timestamp()and not exists(select 1 from private.dsr_file_transfer_completions_v1 c where c.ticket_id=t.id))>=6 then raise exception'DSR_FILE_TRANSFER_RATE_LIMITED'using errcode='54000';end if;
end$$;
create function public.authorize_dsr_file_upload_commit_v1(p_upload_id uuid,p_resume_preparation boolean default false,p_reason text default null)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$declare u public.dsr_redacted_file_uploads_v1%rowtype;o storage.objects%rowtype;ticket uuid;begin
 select*into u from public.dsr_redacted_file_uploads_v1 where id=p_upload_id;perform private.dsr_verified_file_request_v1(u.request_id,true);
 if p_resume_preparation is null or((u.actor_user_id is distinct from auth.uid()or u.status='CANCELLED'or(u.status='RESERVED'and u.expires_at<=clock_timestamp()))and(p_resume_preparation is distinct from true or length(btrim(coalesce(p_reason,'')))not between 10 and 1000))then raise exception'DSR_FILE_UPLOAD_DENIED'using errcode='42501';end if;
 select*into o from storage.objects where bucket_id=u.storage_bucket and name=u.storage_path;
 if o.id is null or o.metadata->>'size'is distinct from u.size_bytes::text or o.metadata->>'mimetype'is distinct from u.mime_type then raise exception'DSR_FILE_STORAGE_MISMATCH'using errcode='22000';end if;
 perform private.dsr_file_transfer_rate_limit_v1();
 insert into private.dsr_file_transfer_tickets_v1(kind,actor_user_id,request_id,payload)values('UPLOAD_COMMIT',auth.uid(),u.request_id,jsonb_build_object('upload_id',u.id,'bucket',u.storage_bucket,'path',u.storage_path,'object_id',o.id,'sha256',u.expected_sha256,'size_bytes',u.size_bytes::text,'mime_type',u.mime_type,'file_name',u.file_name,'resume_preparation',p_resume_preparation,'resume_reason',nullif(btrim(p_reason),'')))returning id into ticket;
 return jsonb_build_object('ticket_id',ticket,'upload_id',u.id,'status',u.status,'scan_status',u.scan_status);
end$$;
create function private.dsr_file_transfer_actor_live_v1(p_ticket private.dsr_file_transfer_tickets_v1)returns boolean language sql stable security definer set search_path=pg_catalog,private set timezone='UTC' as $$select exists(select 1 from auth.users u where u.id=p_ticket.actor_user_id and u.deleted_at is null and(u.banned_until is null or u.banned_until<=statement_timestamp()))and((p_ticket.session_id is null and p_ticket.maintenance_actor)or exists(select 1 from auth.sessions s where s.id=p_ticket.session_id and s.user_id=p_ticket.actor_user_id and(s.not_after is null or s.not_after>statement_timestamp())))$$;
create function public.get_dsr_file_transfer_source_v1(p_ticket_id uuid,p_actor_user_id uuid)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$declare ticket private.dsr_file_transfer_tickets_v1%rowtype;state jsonb;context jsonb;begin
 if auth.role()is distinct from'service_role'then raise exception'DSR_TRUSTED_FILE_PROCESSOR_REQUIRED'using errcode='42501';end if;
 select*into ticket from private.dsr_file_transfer_tickets_v1 where id=p_ticket_id;
 if ticket.id is null or ticket.actor_user_id is distinct from p_actor_user_id or ticket.expires_at<=clock_timestamp()or not private.dsr_file_transfer_actor_live_v1(ticket)then raise exception'DSR_FILE_TRANSFER_EXPIRED'using errcode='42501';end if;
 if ticket.kind<>'RESPONSE_FILE'and not private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN','COMPLIANCE_MANAGER'],ticket.actor_user_id)then raise exception'DSR_RESPONSE_STAFF_REQUIRED'using errcode='42501';end if;
 if not exists(select 1 from public.data_subject_requests where id=ticket.request_id and verified_at is not null)then raise exception'DSR_VERIFIED_SUBJECT_REQUIRED'using errcode='42501';end if;
 if ticket.kind<>'UPLOAD_COMMIT'then state:=private.dsr_file_source_state_v1(ticket.payload->'source_entry');if(state->>'ready')::boolean is distinct from true then raise exception'DSR_TRUSTED_FILE_BYTES_REQUIRED'using errcode='55000';end if;end if;
 if ticket.kind='RESPONSE_FILE'then context:=private.dsr_response_file_context_v1(ticket.response_id,false);if context->>'subject_user_id'is distinct from ticket.actor_user_id::text then raise exception'DSR_VERIFIED_SUBJECT_REQUIRED'using errcode='42501';end if;end if;
 return ticket.payload||jsonb_build_object('kind',ticket.kind);
end$$;
create function public.commit_dsr_redacted_file_bytes_v1(p_ticket_id uuid,p_computed_sha256 text,p_detected_mime_type text,p_size_bytes bigint)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$declare ticket private.dsr_file_transfer_tickets_v1%rowtype;u public.dsr_redacted_file_uploads_v1%rowtype;prior private.dsr_file_transfer_completions_v1%rowtype;h text;begin
 if auth.role()is distinct from'service_role'then raise exception'DSR_TRUSTED_FILE_PROCESSOR_REQUIRED'using errcode='42501';end if;
 select*into ticket from private.dsr_file_transfer_tickets_v1 where id=p_ticket_id;
 h:=private.canonical_request_hash(jsonb_build_object('sha',p_computed_sha256,'mime',p_detected_mime_type,'size',p_size_bytes));
 if ticket.id is null or ticket.kind<>'UPLOAD_COMMIT'then raise exception'DSR_FILE_TRANSFER_EXPIRED'using errcode='42501';end if;
 select*into u from public.dsr_redacted_file_uploads_v1 where id=(ticket.payload->>'upload_id')::uuid for update;
 if ticket.expires_at<=clock_timestamp()or not private.dsr_file_transfer_actor_live_v1(ticket)or not exists(select 1 from public.data_subject_requests where id=ticket.request_id and verified_at is not null and status='IN_REVIEW')or not private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN','COMPLIANCE_MANAGER'],ticket.actor_user_id)then raise exception'DSR_FILE_UPLOAD_DENIED'using errcode='42501';end if;
 if(u.status not in('RESERVED','UPLOADED')and not(u.status='CANCELLED'and(ticket.payload->>'resume_preparation')::boolean))or p_computed_sha256 is distinct from u.expected_sha256 or p_size_bytes is distinct from u.size_bytes or p_detected_mime_type is distinct from u.mime_type or not exists(select 1 from storage.objects where id=(ticket.payload->>'object_id')::uuid and bucket_id=u.storage_bucket and name=u.storage_path and metadata->>'size'=u.size_bytes::text and metadata->>'mimetype'=u.mime_type)then raise exception'DSR_FILE_BYTES_MISMATCH'using errcode='22000';end if;
 select*into prior from private.dsr_file_transfer_completions_v1 where ticket_id=ticket.id;
 if found then if prior.request_hash is distinct from h then raise exception'IDEMPOTENCY_PAYLOAD_MISMATCH'using errcode='22000';end if;return jsonb_build_object('outcome','DSR_REDACTED_FILE_UPLOADED','upload_id',u.id,'scan_status',u.scan_status);end if;
 update public.dsr_redacted_file_uploads_v1 set status='UPLOADED',storage_object_id=(ticket.payload->>'object_id')::uuid,detected_mime_type=p_detected_mime_type where id=u.id;
 insert into private.dsr_file_transfer_completions_v1(ticket_id,request_hash,sha256,size_bytes)values(ticket.id,h,p_computed_sha256,p_size_bytes);
 return jsonb_build_object('outcome','DSR_REDACTED_FILE_UPLOADED','upload_id',u.id,'scan_status',u.scan_status);
end$$;

create function public.claim_dsr_redacted_file_scan_jobs(p_worker_id uuid,p_limit integer default 1,p_lease_seconds integer default 300)returns table(proof_id uuid,lease_token uuid,row_version integer,storage_bucket text,storage_path text,expected_sha256 text,media_type text,size_bytes bigint)language plpgsql security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$declare u public.dsr_redacted_file_uploads_v1%rowtype;c private.dsr_redacted_file_scan_claims_v1%rowtype;begin
 if auth.role()is distinct from'service_role'then raise exception'DSR_TRUSTED_FILE_PROCESSOR_REQUIRED'using errcode='42501';end if;
 if p_worker_id is null or p_limit is null or p_limit not between 1 and 10 or p_lease_seconds is null or p_lease_seconds not between 30 and 600 then raise exception'INVALID_DSR_SCAN_CLAIM'using errcode='22023';end if;
 for u in select upload.*from public.dsr_redacted_file_uploads_v1 upload join public.data_subject_requests d on d.id=upload.request_id left join private.dsr_redacted_file_scan_claims_v1 claim on claim.upload_id=upload.id where upload.status='UPLOADED'and upload.scan_status='PENDING'and d.status='IN_REVIEW'and d.verified_at is not null and(claim.upload_id is null or claim.leased_until<=clock_timestamp())order by upload.created_at,upload.id for update of upload skip locked limit p_limit loop
  insert into private.dsr_redacted_file_scan_claims_v1 as existing(upload_id,worker_id,lease_token,leased_until)values(u.id,p_worker_id,extensions.gen_random_uuid(),clock_timestamp()+make_interval(secs=>p_lease_seconds))on conflict(upload_id)do update set worker_id=p_worker_id,lease_token=extensions.gen_random_uuid(),leased_until=clock_timestamp()+make_interval(secs=>p_lease_seconds),row_version=existing.row_version+1 returning*into c;
  proof_id:=u.id;lease_token:=c.lease_token;row_version:=c.row_version;storage_bucket:=u.storage_bucket;storage_path:=u.storage_path;expected_sha256:=u.expected_sha256;media_type:=u.mime_type;size_bytes:=u.size_bytes;return next;
 end loop;
end$$;
create function public.complete_dsr_redacted_file_scan_job(p_upload_id uuid,p_lease_token uuid,p_worker_id uuid,p_expected_row_version integer,p_result text,p_engine_code text,p_engine_version text,p_computed_sha256 text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$declare u public.dsr_redacted_file_uploads_v1%rowtype;c private.dsr_redacted_file_scan_claims_v1%rowtype;prior private.dsr_redacted_file_scan_results_v1%rowtype;h text;rid uuid:=extensions.gen_random_uuid();n integer;projected_status text;begin
 if auth.role()is distinct from'service_role'then raise exception'DSR_TRUSTED_FILE_PROCESSOR_REQUIRED'using errcode='42501';end if;
 if p_upload_id is null or p_result is null or p_result not in('CLEAN','INFECTED','ERROR')or p_engine_code is null or p_engine_code!~'^[A-Z][A-Z0-9_]{2,99}$'or length(coalesce(p_engine_version,''))not between 1 and 100 or length(coalesce(p_idempotency_key,''))not between 8 and 200 or(p_computed_sha256 is not null and p_computed_sha256!~'^[a-f0-9]{64}$')then raise exception'INVALID_DSR_SCAN_RESULT'using errcode='22023';end if;
 perform private.assert_scan_engine_environment_v1(p_result,p_engine_code);
 h:=private.canonical_request_hash(jsonb_build_object('upload_id',p_upload_id,'result',p_result,'engine_code',p_engine_code,'engine_version',p_engine_version,'computed_sha256',p_computed_sha256));
 select*into u from public.dsr_redacted_file_uploads_v1 where id=p_upload_id for update;
 select*into prior from private.dsr_redacted_file_scan_results_v1 where upload_id=p_upload_id and idempotency_key=p_idempotency_key;
 if found then if prior.request_hash is distinct from h then raise exception'IDEMPOTENCY_PAYLOAD_MISMATCH'using errcode='22000';end if;return jsonb_build_object('outcome','DSR_REDACTED_FILE_SCAN_RECORDED','result_id',prior.id,'result',prior.result);end if;
 select*into c from private.dsr_redacted_file_scan_claims_v1 where upload_id=p_upload_id for update;
 if u.id is null or u.status<>'UPLOADED'or u.scan_status<>'PENDING'or c.upload_id is null or c.worker_id is distinct from p_worker_id or c.lease_token is distinct from p_lease_token or c.row_version is distinct from p_expected_row_version or c.leased_until<=clock_timestamp()then raise exception'DSR_FILE_SCAN_LEASE_INVALID'using errcode='55000';end if;
 if p_result='CLEAN'and u.mime_type='application/zip'then raise exception'ARCHIVE_SCAN_CAPABILITY_REQUIRED'using errcode='55000';end if;
 if p_result in('CLEAN','INFECTED')and(p_computed_sha256 is distinct from u.expected_sha256 or not exists(select 1 from storage.objects o where o.id=u.storage_object_id and o.bucket_id=u.storage_bucket and o.name=u.storage_path))then raise exception'DSR_FILE_SCAN_SOURCE_INVALID'using errcode='22000';end if;
 select coalesce(max(sequence),0)+1 into n from private.dsr_redacted_file_scan_results_v1 where upload_id=u.id;
 insert into private.dsr_redacted_file_scan_results_v1(id,upload_id,sequence,result,computed_sha256,engine_code,engine_version,idempotency_key,request_hash,correlation_id)values(rid,u.id,n,p_result,p_computed_sha256,p_engine_code,p_engine_version,p_idempotency_key,h,coalesce(p_correlation_id,extensions.gen_random_uuid()));
 projected_status:=case p_result when'CLEAN'then'CLEAN'when'INFECTED'then'REJECTED'else'ERROR'end;
 update public.dsr_redacted_file_uploads_v1 set scan_status=projected_status,scan_result_id=rid where id=u.id;
 update private.dsr_redacted_file_scan_claims_v1 set leased_until=clock_timestamp()where upload_id=u.id;
 insert into public.audit_events(organization_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(u.organization_id,'SERVICE','privacy.file.scan_recorded','dsr_file',u.id::text,coalesce(p_correlation_id,extensions.gen_random_uuid()),jsonb_build_object('result_id',rid,'result',p_result,'sequence',n),repeat('0',64));
 insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload)values(u.organization_id,'dsr_file',u.id::text,'DsrRedactedFileScanRecordedV1',coalesce(p_correlation_id,extensions.gen_random_uuid()),jsonb_build_object('upload_id',u.id,'result',p_result));
 return jsonb_build_object('outcome','DSR_REDACTED_FILE_SCAN_RECORDED','result_id',rid,'result',p_result);
end$$;
create function public.fail_dsr_redacted_file_scan_job(p_upload_id uuid,p_lease_token uuid,p_worker_id uuid,p_expected_row_version integer,p_failure_code text,p_computed_sha256 text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$declare u public.dsr_redacted_file_uploads_v1%rowtype;c private.dsr_redacted_file_scan_claims_v1%rowtype;attempt integer;rid uuid:=extensions.gen_random_uuid();n integer;retry_at timestamptz;begin
 if auth.role()is distinct from'service_role'then raise exception'DSR_TRUSTED_FILE_PROCESSOR_REQUIRED'using errcode='42501';end if;
 if p_failure_code is null or p_failure_code!~'^[A-Z][A-Z0-9_]{2,119}$'or(p_computed_sha256 is not null and p_computed_sha256!~'^[a-f0-9]{64}$')then raise exception'INVALID_DSR_SCAN_FAILURE'using errcode='22023';end if;
 select*into u from public.dsr_redacted_file_uploads_v1 where id=p_upload_id for update;select*into c from private.dsr_redacted_file_scan_claims_v1 where upload_id=p_upload_id for update;
 if u.id is null or u.status<>'UPLOADED'or u.scan_status<>'PENDING'or c.upload_id is null or c.worker_id is distinct from p_worker_id or c.lease_token is distinct from p_lease_token or c.row_version is distinct from p_expected_row_version or c.leased_until<=clock_timestamp()then raise exception'DSR_FILE_SCAN_LEASE_INVALID'using errcode='55000';end if;
 attempt:=c.attempt_count+1;retry_at:=clock_timestamp()+make_interval(secs=>least(3600,30*(2^attempt)::integer));
 insert into private.dsr_redacted_file_scan_retries_v1(upload_id,attempt,failure_code,computed_sha256,retry_after)values(u.id,attempt,p_failure_code,p_computed_sha256,case when attempt<5 then retry_at end);
 update private.dsr_redacted_file_scan_claims_v1 set attempt_count=attempt,leased_until=case when attempt<5 then retry_at else clock_timestamp()end,row_version=row_version+1 where upload_id=u.id;
 if attempt>=5 then
  select coalesce(max(sequence),0)+1 into n from private.dsr_redacted_file_scan_results_v1 where upload_id=u.id;
  insert into private.dsr_redacted_file_scan_results_v1(id,upload_id,sequence,result,computed_sha256,engine_code,engine_version,idempotency_key,request_hash,correlation_id)values(rid,u.id,n,'ERROR',p_computed_sha256,'MATRICIA_SCAN_RETRY_LIMIT','1','retry-limit-'||u.id::text||'-'||n::text,private.canonical_request_hash(jsonb_build_object('failure',p_failure_code,'attempt',attempt)),coalesce(p_correlation_id,extensions.gen_random_uuid()));
  update public.dsr_redacted_file_uploads_v1 set scan_status='ERROR',scan_result_id=rid where id=u.id;
 end if;
 insert into public.audit_events(organization_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(u.organization_id,'SERVICE',case when attempt<5 then'privacy.file.scan_retry'else'privacy.file.scan_dead_lettered'end,'dsr_file',u.id::text,coalesce(p_correlation_id,extensions.gen_random_uuid()),jsonb_build_object('failure_code',p_failure_code,'attempt',attempt,'computed_sha256',p_computed_sha256),repeat('0',64));
 return jsonb_build_object('outcome',case when attempt<5 then'DSR_REDACTED_FILE_SCAN_RETRY_SCHEDULED'else'DSR_REDACTED_FILE_SCAN_DEAD_LETTERED'end,'attempt',attempt,'retry_after',case when attempt<5 then retry_at end);
end$$;
create function private.dsr_file_scan_queue_metrics_v1()returns jsonb language sql stable security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$select coalesce(jsonb_agg(to_jsonb(facts)order by status),'[]')from(select case when u.scan_status='ERROR'and(u.status<>'UPLOADED'or d.status<>'IN_REVIEW')then'HISTORICAL_ERROR'when u.scan_status='ERROR'then'DEAD_LETTER'when u.scan_status='PENDING'and coalesce(c.attempt_count,0)>0 then'RETRY_PENDING'else u.scan_status end status,count(*)::text count,greatest(0,coalesce(extract(epoch from statement_timestamp()-min(u.created_at)filter(where u.status='UPLOADED'and d.status='IN_REVIEW'and u.scan_status in('PENDING','ERROR')))::bigint,0))::text oldest_seconds from public.dsr_redacted_file_uploads_v1 u join public.data_subject_requests d on d.id=u.request_id left join private.dsr_redacted_file_scan_claims_v1 c on c.upload_id=u.id where u.status='UPLOADED'or u.scan_status='ERROR'group by 1)facts$$;

create function private.dsr_file_source_state_v1(p_entry jsonb)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$
declare family text:=p_entry->>'source_type';source_id text:=p_entry->>'source_id';row_data jsonb;object storage.objects%rowtype;proof jsonb;ready boolean:=false;table_name text;begin
 if family='EXTERNAL_DSR_EXPORT'or family='auth.users.avatar'then return jsonb_build_object('ready',false,'reason','DSR_PROVIDED_FILE_REQUIRED');end if;
 if family='public.client_commercial_document_artifacts'then select to_jsonb(a)into row_data from public.client_commercial_document_artifacts a where a.document_id=split_part(source_id,':',1)::uuid and a.locale=split_part(source_id,':',2);
 elsif family='private.signature_native_cancellation_attestations_v1'then select to_jsonb(a)into row_data from private.signature_native_cancellation_attestations_v1 a where a.envelope_id=source_id::uuid;
 elsif family='storage.delivery_orphan'then select to_jsonb(a)into row_data from storage.objects a where a.id=source_id::uuid;
 else
  table_name:=split_part(family,':',1);
  if table_name<>all(array['public.client_compliance_documents','public.provider_document_versions','public.provider_document_upload_reservations','public.provider_document_scan_jobs','public.provider_payment_proof_uploads','public.provider_payment_proofs','public.provider_payable_event_proofs','public.delivery_proofs','public.internal_message_attachment_uploads','public.internal_message_attachments','public.provider_billing_document_artifacts','private.contract_signature_source_artifacts_v1','public.signature_documents','public.signature_signer_authorities','public.dispute_evidence','public.brand_assets','public.social_media_assets','public.organization_export_artifacts','public.privacy_notices','public.data_subject_requests','public.admin_external_validation_evidence_versions','private.franchise_mandate_signature_proofs_v1','public.dsr_redacted_file_uploads_v1','public.dsr_private_responses_v1'])then return jsonb_build_object('ready',false,'reason','DSR_FILE_SOURCE_UNSUPPORTED');end if;
  execute format('select to_jsonb(r)from %s r where id=$1',table_name)into row_data using source_id::uuid;
 end if;
 if row_data is null or(case when p_entry->>'source_identity_hash'is not null then private.dsr_file_source_identity_hash_v1(row_data)is distinct from p_entry->>'source_identity_hash'else private.canonical_request_hash(row_data)is distinct from coalesce(p_entry->>'primary_source_hash',p_entry->>'source_hash')end)then return jsonb_build_object('ready',false,'reason','DSR_FILE_SOURCE_CHANGED');end if;
 if p_entry->>'trust_kind'='INLINE_DSR_RESPONSE'then
  ready:=row_data->>'sha256'=p_entry->>'sha256'and octet_length(row_data->>'response_json')::text=p_entry->>'size_bytes';
  return jsonb_build_object('ready',ready,'content_kind','INLINE','content',case when ready then row_data->>'response_json'end,'sha256',p_entry->>'sha256','size_bytes',p_entry->>'size_bytes','mime_type','application/json','file_name',p_entry->>'file_name');
 end if;
 if coalesce(p_entry->>'sha256','')!~'^[a-f0-9]{64}$'or coalesce(p_entry->>'size_bytes','')!~'^[0-9]{1,10}$'or(p_entry->>'size_bytes')::bigint not between 1 and 33554432 or p_entry->>'bucket'is null or p_entry->>'path'is null then return jsonb_build_object('ready',false,'reason','DSR_FILE_SOURCE_BYTES_UNAVAILABLE');end if;
 select o.*into object from storage.objects o join storage.buckets b on b.id=o.bucket_id where o.id=(p_entry->>'storage_object_id')::uuid and o.bucket_id=p_entry->>'bucket'and o.name=p_entry->>'path'and not b.public;
 if object.id is null or object.metadata->>'size'is distinct from p_entry->>'size_bytes'then return jsonb_build_object('ready',false,'reason','DSR_FILE_SOURCE_BYTES_UNAVAILABLE');end if;
 case p_entry->>'trust_kind'
 when'CLIENT_DOCUMENT'then
  select to_jsonb(scan)into proof from private.client_document_scan_results scan where scan.id=(row_data->>'current_scan_result_id')::uuid and scan.document_id=source_id::uuid and scan.result='CLEAN'and scan.computed_sha256=p_entry->>'sha256'and scan.sequence=(select max(sequence)from private.client_document_scan_results where document_id=source_id::uuid)and row_data->>'scan_status'='CLEAN';ready:=proof is not null;
 when'PROVIDER_DOCUMENT'then
  select to_jsonb(scan)into proof from public.provider_document_scan_jobs j join private.provider_document_scan_results scan on scan.id=j.current_scan_result_id where j.provider_organization_id=(row_data->>'provider_organization_id')::uuid and j.storage_object_path=p_entry->>'path'and j.scan_status='CLEAN'and scan.result='CLEAN'and scan.computed_sha256=p_entry->>'sha256'order by scan.recorded_at desc limit 1;ready:=proof is not null;
 when'PROVIDER_SCAN_JOB'then
  select to_jsonb(scan)into proof from private.provider_document_scan_results scan where scan.id=(row_data->>'current_scan_result_id')::uuid and scan.result='CLEAN'and scan.computed_sha256=p_entry->>'sha256'and row_data->>'scan_status'='CLEAN';ready:=proof is not null;
 when'PAYMENT_UPLOAD'then
  select to_jsonb(scan)into proof from private.provider_payment_proof_scan_results scan where scan.id=(row_data->>'current_scan_result_id')::uuid and scan.upload_id=source_id::uuid and scan.result='CLEAN'and scan.computed_sha256=p_entry->>'sha256'and row_data->>'scan_status'='CLEAN';ready:=proof is not null;
 when'PAYMENT_PROOF','PAYABLE_PROOF'then
  select to_jsonb(scan)into proof from public.provider_payment_proof_uploads u join private.provider_payment_proof_scan_results scan on scan.id=u.current_scan_result_id where u.id=(row_data->>'upload_id')::uuid and u.scan_status='CLEAN'and scan.result='CLEAN'and scan.computed_sha256=p_entry->>'sha256';ready:=proof is not null;
 when'DELIVERY_PROOF'then
  select to_jsonb(scan)into proof from private.delivery_proof_scan_results scan where scan.id=(row_data->>'current_scan_result_id')::uuid and scan.proof_id=source_id::uuid and scan.result='CLEAN'and scan.computed_sha256=p_entry->>'sha256'and row_data->>'scan_status'='CLEAN';ready:=proof is not null;
 when'MESSAGE_UPLOAD'then
  select to_jsonb(scan)into proof from private.internal_message_attachment_scan_results scan where scan.id=(row_data->>'scan_result_id')::uuid and scan.upload_id=source_id::uuid and scan.result='CLEAN'and scan.computed_sha256=p_entry->>'sha256'and row_data->>'scan_status'='CLEAN'and row_data->>'status'in('UPLOADED','BOUND');ready:=proof is not null;
 when'MESSAGE_ATTACHMENT'then
  select to_jsonb(scan)into proof from public.internal_message_attachment_uploads u join private.internal_message_attachment_scan_results scan on scan.id=u.scan_result_id where u.id=(row_data->>'trusted_upload_id')::uuid and u.attachment_id=source_id::uuid and u.status='BOUND'and u.scan_status='CLEAN'and scan.result='CLEAN'and scan.computed_sha256=p_entry->>'sha256';ready:=proof is not null;
 when'DSR_REDACTED'then
  select to_jsonb(scan)into proof from private.dsr_redacted_file_scan_results_v1 scan where scan.id=(row_data->>'scan_result_id')::uuid and scan.upload_id=source_id::uuid and scan.result='CLEAN'and scan.computed_sha256=p_entry->>'sha256'and row_data->>'mime_type'<>'application/zip'and row_data->>'status'in('UPLOADED','CANCELLED')and row_data->>'scan_status'='CLEAN'and(row_data->>'storage_object_id')::uuid=object.id;ready:=proof is not null;
 when'PROVIDER_PDF'then ready:=row_data->>'pdf_sha256'=p_entry->>'sha256'and row_data->>'policy_binding_id'is not null;
 when'CLIENT_PDF'then ready:=row_data->>'renderer_version'='CLIENT_BILLING_PDF_V1'and row_data->>'pdf_sha256'=p_entry->>'sha256';
 when'CONTRACT_PDF'then ready:=row_data->>'render_version'='SIGNATURE_SOURCE_PDF_V1'and row_data->>'verification_reference'='HTTP_READBACK_SHA256_V1'and(row_data->>'storage_object_id')::uuid=object.id;
 when'SIGNATURE_DOCUMENT'then ready:=exists(select 1 from private.contract_signature_source_artifacts_v1 a where a.contract_version_id=(row_data->>'contract_version_id')::uuid and a.render_version='SIGNATURE_SOURCE_PDF_V1'and a.verification_reference='HTTP_READBACK_SHA256_V1'and a.storage_object_id=object.id and a.storage_path=p_entry->>'path'and a.pdf_sha256=p_entry->>'sha256');
 else ready:=false;
 end case;
 if ready and proof is not null then begin perform private.assert_scan_engine_environment_v1('CLEAN',proof->>'engine_code');exception when sqlstate'42501'then ready:=false;end;end if;
 return jsonb_build_object('ready',ready,'reason',case when not ready then'DSR_TRUSTED_FILE_BYTES_REQUIRED'end,'content_kind','STORAGE','bucket',p_entry->>'bucket','path',p_entry->>'path','sha256',p_entry->>'sha256','size_bytes',p_entry->>'size_bytes','mime_type',coalesce(nullif(p_entry->>'mime_type',''),'application/octet-stream'),'file_name',p_entry->>'file_name','storage_object_id',object.id);
exception when invalid_text_representation or numeric_value_out_of_range then return jsonb_build_object('ready',false,'reason','DSR_FILE_SOURCE_INVALID');
end$$;
create function private.dsr_redacted_file_entry_v1(p_upload_id uuid,p_request_id uuid)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$declare u public.dsr_redacted_file_uploads_v1%rowtype;begin
 select*into u from public.dsr_redacted_file_uploads_v1 where id=p_upload_id and request_id=p_request_id;
 if u.id is null then raise exception'DSR_REDACTED_FILE_SCOPE_DENIED'using errcode='42501';end if;
 return private.dsr_file_candidate_v1('public.dsr_redacted_file_uploads_v1',u.id::text,to_jsonb(u),u.storage_bucket,u.storage_path,u.expected_sha256,u.size_bytes,u.mime_type,u.file_name,'DSR_REDACTED');
end$$;

create table public.dsr_file_disposition_proposals_v1(
 id uuid primary key default extensions.gen_random_uuid(),package_id uuid not null references public.dsr_all_packages_v1(id),entry_id text not null check(entry_id~'^[a-f0-9]{64}$'),version integer not null check(version>0),source_hash text not null check(source_hash~'^[a-f0-9]{64}$'),disposition text not null check(disposition in('INCLUDE_ORIGINAL','INCLUDE_REDACTED','INCLUDE_EXTERNAL_EXPORT','EXCLUDE')),output_upload_ids uuid[]not null default'{}'check(cardinality(output_upload_ids)<=100),output_snapshots jsonb not null,cut_source_sha256 text not null check(cut_source_sha256~'^[a-f0-9]{64}$'),legal_reference text,provenance_reference text,reason text not null check(length(btrim(reason))between 10 and 2000),content_hash text not null check(content_hash~'^[a-f0-9]{64}$'),created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),idempotency_key uuid not null,unique(created_by,idempotency_key),unique(package_id,entry_id,version)
);
create table public.dsr_file_disposition_decisions_v1(proposal_id uuid primary key references public.dsr_file_disposition_proposals_v1(id),decision text not null check(decision in('APPROVE','REJECT')),content_hash text not null,review_proof_hash text not null,reason text not null check(length(btrim(reason))between 10 and 2000),legal_reference text,decided_by uuid not null references auth.users(id),decided_at timestamptz not null default clock_timestamp());
create table private.dsr_file_output_sources_v1(id text primary key check(id~'^[a-f0-9]{64}$'),proposal_id uuid not null references public.dsr_file_disposition_proposals_v1(id),source_snapshot jsonb not null);
create table private.dsr_response_file_ack_v1(response_id uuid not null references public.dsr_private_responses_v1(id),entry_id text not null,subject_user_id uuid not null references auth.users(id),response_sha256 text not null,file_manifest_hash text not null,download_sha256 text not null,source_hash text not null,acknowledged_at timestamptz not null default clock_timestamp(),primary key(response_id,entry_id));
do $$declare s text;t text;begin foreach t in array array['dsr_file_disposition_proposals_v1','dsr_file_disposition_decisions_v1','dsr_response_file_ack_v1','dsr_file_output_sources_v1']loop s:=case when t in('dsr_response_file_ack_v1','dsr_file_output_sources_v1')then'private'else'public'end;execute format('alter table %I.%I enable row level security',s,t);execute format('revoke all on %I.%I from public,anon,authenticated,service_role',s,t);execute format('create trigger %I before update or delete on %I.%I for each row execute function private.prevent_update_delete()',left(t,43)||'_immutable',s,t);end loop;end$$;
create function private.dsr_package_file_entry_v1(p_package_id uuid,p_entry_id text)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$declare package public.dsr_all_packages_v1%rowtype;sources jsonb;entry jsonb;begin
 select*into package from public.dsr_all_packages_v1 where id=p_package_id;sources:=package.snapshot_json::jsonb->'file_sources';
 if package.id is null or p_entry_id is null or p_entry_id!~'^[a-f0-9]{64}$'or jsonb_typeof(sources->'entries')is distinct from'array'or sources->>'hash'is distinct from private.canonical_request_hash(sources->'entries')then raise exception'DSR_CAPTURED_FILE_SOURCE_REQUIRED'using errcode='55000';end if;
 select value into entry from jsonb_array_elements(sources->'entries')where value->>'id'=p_entry_id;
 if entry is null then raise exception'DSR_CAPTURED_FILE_SOURCE_REQUIRED'using errcode='55000';end if;return entry;
end$$;
create function private.dsr_file_reviewed_bytes_v1(p_actor uuid,p_package_id uuid,p_entry_id text,p_source_hash text,p_sha256 text)returns boolean language sql stable security definer set search_path=pg_catalog,private set timezone='UTC' as $$select exists(select 1 from private.dsr_file_transfer_tickets_v1 t join private.dsr_file_transfer_completions_v1 c on c.ticket_id=t.id where t.actor_user_id=p_actor and t.kind in('SOURCE_REVIEW','REDACTED_REVIEW')and t.package_id=p_package_id and t.entry_id=p_entry_id and t.source_hash=p_source_hash and c.sha256=p_sha256)$$;
create function private.dsr_validate_file_outputs_v1(p_package_id uuid,p_entry_id text,p_disposition text,p_upload_ids uuid[],p_actor uuid,p_require_byte_review boolean)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$declare package public.dsr_all_packages_v1%rowtype;entry jsonb;output jsonb;state jsonb;uid uuid;outputs jsonb:='[]';begin
 select*into package from public.dsr_all_packages_v1 where id=p_package_id;entry:=private.dsr_package_file_entry_v1(p_package_id,p_entry_id);
 if p_disposition='EXCLUDE'then if cardinality(p_upload_ids)<>0 then raise exception'DSR_EXCLUDED_FILE_CANNOT_HAVE_OUTPUTS'using errcode='22023';end if;return outputs;end if;
 if p_disposition='INCLUDE_ORIGINAL'then
  if cardinality(p_upload_ids)<>0 or entry->>'source_type'='EXTERNAL_DSR_EXPORT'then raise exception'INVALID_DSR_FILE_OUTPUTS'using errcode='22023';end if;
  state:=private.dsr_file_source_state_v1(entry);if(state->>'ready')::boolean is distinct from true then raise exception'DSR_TRUSTED_FILE_BYTES_REQUIRED'using errcode='55000';end if;
  if p_require_byte_review and not private.dsr_file_reviewed_bytes_v1(p_actor,package.id,p_entry_id,entry->>'source_hash',state->>'sha256')then raise exception'DSR_EXACT_FILE_REVIEW_ACCESS_REQUIRED'using errcode='55000';end if;
  return jsonb_build_array(entry);
 end if;
 if cardinality(p_upload_ids)not between 1 and 100 or(p_disposition='INCLUDE_EXTERNAL_EXPORT')is distinct from(entry->>'source_type'='EXTERNAL_DSR_EXPORT')then raise exception'INVALID_DSR_FILE_OUTPUTS'using errcode='22023';end if;
 foreach uid in array p_upload_ids loop
  output:=private.dsr_redacted_file_entry_v1(uid,package.request_id);state:=private.dsr_file_source_state_v1(output);
  if(state->>'ready')::boolean is distinct from true then raise exception'DSR_TRUSTED_FILE_BYTES_REQUIRED'using errcode='55000';end if;
  if p_disposition='INCLUDE_REDACTED'and output->>'sha256'=entry->>'sha256'then raise exception'DSR_REDACTED_FILE_MUST_BE_DISTINCT'using errcode='22023';end if;
  if p_require_byte_review and not private.dsr_file_reviewed_bytes_v1(p_actor,package.id,uid::text,output->>'source_hash',state->>'sha256')then raise exception'DSR_EXACT_FILE_REVIEW_ACCESS_REQUIRED'using errcode='55000';end if;
  outputs:=outputs||jsonb_build_array(output);
 end loop;return outputs;
end$$;
create function public.propose_dsr_file_disposition_v1(p_package_id uuid,p_entry_id text,p_expected_source_hash text,p_expected_cut_sha256 text,p_disposition text,p_output_upload_ids uuid[],p_legal_reference text,p_provenance_reference text,p_reason text,p_personal_scope_confirmed boolean,p_third_party_review_confirmed boolean,p_as_of_cut_confirmed boolean,p_idempotency_key uuid)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$declare package public.dsr_all_packages_v1%rowtype;entry jsonb;prior public.dsr_file_disposition_proposals_v1%rowtype;ids uuid[];outputs jsonb;h text;v integer;pid uuid:=extensions.gen_random_uuid();begin
 if not coalesce(private.dsr_response_staff_v1(),false)then raise exception'DSR_RESPONSE_STAFF_REQUIRED'using errcode='42501';end if;
 if p_idempotency_key is null or p_disposition is null or p_disposition not in('INCLUDE_ORIGINAL','INCLUDE_REDACTED','INCLUDE_EXTERNAL_EXPORT','EXCLUDE')or p_personal_scope_confirmed is distinct from true or p_third_party_review_confirmed is distinct from true or p_as_of_cut_confirmed is distinct from true or length(btrim(coalesce(p_reason,'')))not between 10 and 2000 or p_output_upload_ids is null or cardinality(p_output_upload_ids)>100 or exists(select 1 from unnest(p_output_upload_ids)id where id is null)then raise exception'DSR_FILE_SCOPE_AND_THIRD_PARTY_REVIEW_REQUIRED'using errcode='22023';end if;
 select coalesce(array_agg(id order by id),'{}')into ids from(select distinct unnest(p_output_upload_ids)id)items;
 if p_disposition='EXCLUDE'and length(btrim(coalesce(p_legal_reference,'')))not between 3 and 500 then raise exception'DSR_FILE_LEGAL_EXCLUSION_REFERENCE_REQUIRED'using errcode='22023';end if;
 if p_disposition in('INCLUDE_REDACTED','INCLUDE_EXTERNAL_EXPORT')and length(btrim(coalesce(p_provenance_reference,'')))not between 10 and 1000 then raise exception'DSR_FILE_AS_OF_CUT_PROVENANCE_REQUIRED'using errcode='22023';end if;
 h:=private.canonical_request_hash(jsonb_build_object('package',p_package_id,'entry',p_entry_id,'source_hash',p_expected_source_hash,'cut_sha256',p_expected_cut_sha256,'disposition',p_disposition,'outputs',ids,'legal_reference',nullif(btrim(p_legal_reference),''),'provenance_reference',nullif(btrim(p_provenance_reference),''),'reason',btrim(p_reason),'actor',auth.uid()));
 perform pg_advisory_xact_lock(hashtextextended('dsr-file-proposal:'||auth.uid()::text||':'||p_idempotency_key::text,0));select*into prior from public.dsr_file_disposition_proposals_v1 where created_by=auth.uid()and idempotency_key=p_idempotency_key;
 if found then if prior.content_hash is distinct from h then raise exception'IDEMPOTENCY_PAYLOAD_MISMATCH'using errcode='22000';end if;return jsonb_build_object('outcome','DSR_FILE_DISPOSITION_PROPOSED','proposal_id',prior.id,'content_hash',prior.content_hash);end if;
 select*into package from public.dsr_all_packages_v1 where id=p_package_id;perform private.dsr_verified_file_request_v1(package.request_id,true);
 if package.source_sha256 is distinct from p_expected_cut_sha256 or package.scope_version_id is distinct from(select id from public.dsr_scope_versions_v1 where request_id=package.request_id order by version desc limit 1)then raise exception'STALE_DSR_FILE_CONTEXT'using errcode='40001';end if;
 entry:=private.dsr_package_file_entry_v1(package.id,p_entry_id);if entry->>'source_hash'is distinct from p_expected_source_hash then raise exception'STALE_DSR_FILE_CONTEXT'using errcode='40001';end if;
 outputs:=private.dsr_validate_file_outputs_v1(package.id,p_entry_id,p_disposition,ids,auth.uid(),true);
 perform pg_advisory_xact_lock(hashtextextended('dsr-file-disposition:'||package.id::text||':'||p_entry_id,0));select coalesce(max(version),0)+1 into v from public.dsr_file_disposition_proposals_v1 where package_id=package.id and entry_id=p_entry_id;
 insert into public.dsr_file_disposition_proposals_v1(id,package_id,entry_id,version,source_hash,disposition,output_upload_ids,output_snapshots,cut_source_sha256,legal_reference,provenance_reference,reason,content_hash,created_by,idempotency_key)values(pid,package.id,p_entry_id,v,p_expected_source_hash,p_disposition,ids,outputs,package.source_sha256,nullif(btrim(p_legal_reference),''),nullif(btrim(p_provenance_reference),''),btrim(p_reason),h,auth.uid(),p_idempotency_key);
 insert into private.dsr_file_output_sources_v1(id,proposal_id,source_snapshot)select private.canonical_request_hash(jsonb_build_object('proposal_id',pid,'source_entry_id',p_entry_id,'output_source_id',value->>'source_id','sha256',value->>'sha256')),pid,value from jsonb_array_elements(outputs);
 insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(package.organization_id,auth.uid(),'USER','privacy.file.disposition_proposed','dsr_file_disposition',pid::text,pid,jsonb_build_object('package_id',package.id,'entry_id',p_entry_id,'source_hash',p_expected_source_hash,'disposition',p_disposition,'content_hash',h),repeat('0',64));
 return jsonb_build_object('outcome','DSR_FILE_DISPOSITION_PROPOSED','proposal_id',pid,'content_hash',h);
end$$;
create function public.decide_dsr_file_disposition_v1(p_proposal_id uuid,p_expected_content_hash text,p_approve boolean,p_scope_and_third_party_review_confirmed boolean,p_legal_reference text,p_reason text)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$declare proposal public.dsr_file_disposition_proposals_v1%rowtype;prior public.dsr_file_disposition_decisions_v1%rowtype;package public.dsr_all_packages_v1%rowtype;outputs jsonb;proof text;decision text:=case when p_approve then'APPROVE'else'REJECT'end;begin
 if not coalesce(private.dsr_response_staff_v1(),false)then raise exception'DSR_RESPONSE_STAFF_REQUIRED'using errcode='42501';end if;
 select*into proposal from public.dsr_file_disposition_proposals_v1 where id=p_proposal_id for update;
 if proposal.id is null or proposal.created_by=auth.uid()then raise exception'DSR_INDEPENDENT_FILE_REVIEW_REQUIRED'using errcode='42501';end if;
 if proposal.content_hash is distinct from p_expected_content_hash then raise exception'STALE_DSR_FILE_CONTEXT'using errcode='40001';end if;
 if p_approve is null or p_scope_and_third_party_review_confirmed is distinct from true or length(btrim(coalesce(p_reason,'')))not between 10 and 2000 or(proposal.disposition='EXCLUDE'and length(btrim(coalesce(p_legal_reference,'')))not between 3 and 500)then raise exception'DSR_FILE_SCOPE_AND_THIRD_PARTY_REVIEW_REQUIRED'using errcode='22023';end if;
 select*into prior from public.dsr_file_disposition_decisions_v1 where proposal_id=proposal.id;
 if found then if prior.decision is distinct from decision or prior.decided_by is distinct from auth.uid()or prior.reason is distinct from btrim(p_reason)or prior.legal_reference is distinct from nullif(btrim(p_legal_reference),'')then raise exception'DSR_FILE_DISPOSITION_ALREADY_REVIEWED'using errcode='55000';end if;return jsonb_build_object('outcome','DSR_FILE_DISPOSITION_REVIEWED','proposal_id',proposal.id,'decision',prior.decision,'review_proof_hash',prior.review_proof_hash);end if;
 select*into package from public.dsr_all_packages_v1 where id=proposal.package_id;perform private.dsr_verified_file_request_v1(package.request_id,true);
 if package.scope_version_id is distinct from(select id from public.dsr_scope_versions_v1 where request_id=package.request_id order by version desc limit 1)then raise exception'STALE_DSR_FILE_CONTEXT'using errcode='40001';end if;
 if p_approve then outputs:=private.dsr_validate_file_outputs_v1(package.id,proposal.entry_id,proposal.disposition,proposal.output_upload_ids,auth.uid(),true);if outputs is distinct from proposal.output_snapshots then raise exception'STALE_DSR_FILE_CONTEXT'using errcode='40001';end if;end if;
 proof:=private.canonical_request_hash(jsonb_build_object('proposal_hash',proposal.content_hash,'outputs',proposal.output_snapshots,'decision',decision,'reviewer',auth.uid(),'legal_reference',nullif(btrim(p_legal_reference),''),'reason',btrim(p_reason)));
 insert into public.dsr_file_disposition_decisions_v1(proposal_id,decision,content_hash,review_proof_hash,reason,legal_reference,decided_by)values(proposal.id,decision,proposal.content_hash,proof,btrim(p_reason),nullif(btrim(p_legal_reference),''),auth.uid());
 insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(package.organization_id,auth.uid(),'USER','privacy.file.disposition_reviewed','dsr_file_disposition',proposal.id::text,proposal.id,jsonb_build_object('package_id',package.id,'entry_id',proposal.entry_id,'decision',decision,'review_proof_hash',proof,'content_hash',proposal.content_hash),repeat('0',64));
 return jsonb_build_object('outcome','DSR_FILE_DISPOSITION_REVIEWED','proposal_id',proposal.id,'decision',decision,'review_proof_hash',proof);
end$$;

create function private.dsr_file_manifest_revision_v1(p_package_id uuid)returns text language sql stable security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$select private.canonical_request_hash(coalesce(jsonb_agg(jsonb_build_object('entry_id',entry_id,'proposal_id',id,'content_hash',content_hash,'review_proof_hash',review_proof_hash)order by entry_id),'[]'))from(select distinct on(p.entry_id)p.entry_id,p.id,p.content_hash,d.review_proof_hash from public.dsr_file_disposition_proposals_v1 p join public.dsr_file_disposition_decisions_v1 d on d.proposal_id=p.id and d.decision='APPROVE'and d.content_hash=p.content_hash and d.decided_by<>p.created_by where p.package_id=p_package_id order by p.entry_id,p.version desc)effective$$;
create function private.dsr_all_file_manifest_v1(p_package_id uuid)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$declare package public.dsr_all_packages_v1%rowtype;sources jsonb;entry jsonb;proposal public.dsr_file_disposition_proposals_v1%rowtype;decision public.dsr_file_disposition_decisions_v1%rowtype;output jsonb;state jsonb;items jsonb:='[]';complete boolean:=true;output_id text;begin
 select*into package from public.dsr_all_packages_v1 where id=p_package_id;sources:=package.snapshot_json::jsonb->'file_sources';
 if package.id is null or jsonb_typeof(sources->'entries')is distinct from'array'or sources->>'hash'is distinct from private.canonical_request_hash(sources->'entries')or coalesce((sources->>'coverage_complete')::boolean,false)is not true then complete:=false;end if;
 for entry in select value from jsonb_array_elements(coalesce(sources->'entries','[]'))loop
  select p.*into proposal from public.dsr_file_disposition_proposals_v1 p join public.dsr_file_disposition_decisions_v1 d on d.proposal_id=p.id and d.decision='APPROVE'and d.content_hash=p.content_hash and d.decided_by<>p.created_by where p.package_id=package.id and p.entry_id=entry->>'id'and p.source_hash=entry->>'source_hash'and p.cut_source_sha256=package.source_sha256 order by p.version desc limit 1;
  if proposal.id is null then complete:=false;items:=items||jsonb_build_array(jsonb_build_object('id',entry->>'id','source_entry_id',entry->>'id','source_hash',entry->>'source_hash','disposition','PENDING','ready',false));continue;end if;
  select*into decision from public.dsr_file_disposition_decisions_v1 where proposal_id=proposal.id;
  if proposal.disposition='EXCLUDE'then items:=items||jsonb_build_array(jsonb_build_object('id',entry->>'id','source_entry_id',entry->>'id','source_hash',entry->>'source_hash','disposition','EXCLUDE','ready',true,'download_sha256',null,'size_bytes',null,'mime_type',null,'file_name',null,'legal_reference',proposal.legal_reference,'review_legal_reference',decision.legal_reference,'reason',proposal.reason,'review_proof_hash',decision.review_proof_hash));continue;end if;
  if jsonb_array_length(proposal.output_snapshots)=0 then complete:=false;end if;
  for output in select value from jsonb_array_elements(proposal.output_snapshots)loop
   state:=private.dsr_file_source_state_v1(output);output_id:=private.canonical_request_hash(jsonb_build_object('proposal_id',proposal.id,'source_entry_id',proposal.entry_id,'output_source_id',output->>'source_id','sha256',output->>'sha256'));
   if(state->>'ready')::boolean is distinct from true then complete:=false;end if;
   items:=items||jsonb_build_array(jsonb_build_object('id',output_id,'source_entry_id',entry->>'id','source_hash',entry->>'source_hash','disposition',proposal.disposition,'ready',coalesce((state->>'ready')::boolean,false),'download_sha256',output->>'sha256','size_bytes',output->>'size_bytes','mime_type',output->>'mime_type','file_name',output->>'file_name','legal_reference',proposal.legal_reference,'provenance_reference',proposal.provenance_reference,'reason',proposal.reason,'review_proof_hash',decision.review_proof_hash));
  end loop;
 end loop;
 return jsonb_build_object('complete',complete,'revision_hash',private.dsr_file_manifest_revision_v1(package.id),'manifest_hash',private.canonical_request_hash(jsonb_build_object('package_id',package.id,'source_sha256',package.source_sha256,'revision_hash',private.dsr_file_manifest_revision_v1(package.id),'coverage_complete',coalesce((sources->>'coverage_complete')::boolean,false),'complete',complete,'entries',items)),'entries',items);
end$$;
-- No actor check is placed on this internal manifest/ack predicate: the guarded
-- subject response commands also invoke it under the subject's JWT.
create function private.dsr_response_file_context_v1(p_response_id uuid,p_require_subject boolean)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$declare response public.dsr_private_responses_v1%rowtype;binding public.dsr_all_response_packages_v1%rowtype;manifest jsonb;begin
 select*into response from public.dsr_private_responses_v1 where id=p_response_id;select*into binding from public.dsr_all_response_packages_v1 where response_id=response.id;
 if response.id is null or binding.response_id is null or binding.disclosure_hash is distinct from response.sha256 or not exists(select 1 from public.dsr_all_packages_v1 package join public.data_subject_requests request on request.id=package.request_id where package.id=binding.package_id and package.request_id=response.request_id and package.scope_version_id=response.scope_version_id and package.subject_user_id=response.subject_user_id and package.organization_id=request.organization_id and request.subject_reference_hash=encode(extensions.digest(convert_to(request.organization_id::text||':'||response.subject_user_id::text,'UTF8'),'sha256'),'hex'))then raise exception'DSR_APPROVED_RESPONSE_REQUIRED'using errcode='42501';end if;
 if p_require_subject and(not private.current_auth_session_active_v1()or auth.uid()is null or auth.jwt()->>'aal'is distinct from'aal2'or auth.uid()is distinct from response.subject_user_id)then raise exception'DSR_VERIFIED_SUBJECT_REQUIRED'using errcode='42501';end if;
 if not exists(select 1 from public.data_subject_requests where id=response.request_id and verified_at is not null)or not exists(select 1 from public.dsr_private_response_decisions_v1 where response_id=response.id and sha256=response.sha256 and decision='APPROVE'and decided_by<>response.created_by)then raise exception'DSR_APPROVED_RESPONSE_REQUIRED'using errcode='42501';end if;
 manifest:=response.response_json::jsonb->'file_manifest';
 if manifest->>'revision_hash'is distinct from private.dsr_file_manifest_revision_v1(binding.package_id)or manifest->>'manifest_hash'is distinct from binding.file_manifest_hash then raise exception'DSR_RESPONSE_FILE_MANIFEST_CHANGED'using errcode='40001';end if;
 return jsonb_build_object('response_id',response.id,'request_id',response.request_id,'subject_user_id',response.subject_user_id,'response_sha256',response.sha256,'package_id',binding.package_id,'file_manifest_hash',binding.file_manifest_hash,'manifest',manifest);
end$$;
create function private.dsr_manifest_output_source_v1(p_package_id uuid,p_file_id text)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$declare output jsonb;begin
 select f.source_snapshot into output from private.dsr_file_output_sources_v1 f join public.dsr_file_disposition_proposals_v1 p on p.id=f.proposal_id join public.dsr_file_disposition_decisions_v1 d on d.proposal_id=p.id and d.decision='APPROVE'and d.content_hash=p.content_hash and d.decided_by<>p.created_by where f.id=p_file_id and p.package_id=p_package_id and not exists(select 1 from public.dsr_file_disposition_proposals_v1 newer join public.dsr_file_disposition_decisions_v1 nd on nd.proposal_id=newer.id and nd.decision='APPROVE'and nd.content_hash=newer.content_hash where newer.package_id=p.package_id and newer.entry_id=p.entry_id and newer.version>p.version);
 if output is null then raise exception'DSR_APPROVED_FILE_NOT_AVAILABLE'using errcode='55000';end if;return output;
end$$;
create function public.authorize_dsr_file_review_v1(p_package_id uuid,p_entry_id text,p_redacted_upload_id uuid default null)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$declare package public.dsr_all_packages_v1%rowtype;entry jsonb;state jsonb;ticket uuid;kind text;review_key text;begin
 select*into package from public.dsr_all_packages_v1 where id=p_package_id;perform private.dsr_verified_file_request_v1(package.request_id,false);
 if p_redacted_upload_id is null then entry:=private.dsr_package_file_entry_v1(package.id,p_entry_id);kind:='SOURCE_REVIEW';review_key:=p_entry_id;
 else entry:=private.dsr_redacted_file_entry_v1(p_redacted_upload_id,package.request_id);kind:='REDACTED_REVIEW';review_key:=p_redacted_upload_id::text;end if;
 state:=private.dsr_file_source_state_v1(entry);if(state->>'ready')::boolean is distinct from true then raise exception'DSR_TRUSTED_FILE_BYTES_REQUIRED'using errcode='55000';end if;
 perform private.dsr_file_transfer_rate_limit_v1();
 insert into private.dsr_file_transfer_tickets_v1(kind,actor_user_id,request_id,package_id,entry_id,source_hash,payload)values(kind,auth.uid(),package.request_id,package.id,review_key,entry->>'source_hash',state||jsonb_build_object('source_entry',entry))returning id into ticket;
 return jsonb_build_object('ticket_id',ticket,'sha256',state->>'sha256','size_bytes',state->>'size_bytes','mime_type',state->>'mime_type','file_name',state->>'file_name');
end$$;
create function public.get_my_dsr_response_files_v1(p_response_id uuid,p_page integer default 1)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$declare context jsonb;items jsonb;total integer;begin
 if p_page is null or p_page not between 1 and 10000 then raise exception'INVALID_DSR_FILE_PAGE'using errcode='22023';end if;
 context:=private.dsr_response_file_context_v1(p_response_id,true);total:=jsonb_array_length(context#>'{manifest,entries}');
 select coalesce(jsonb_agg(entry order by ord),'[]')into items from(select value||jsonb_build_object('ready',case when value->>'disposition'='EXCLUDE'then true when value->>'disposition'in('INCLUDE_ORIGINAL','INCLUDE_REDACTED','INCLUDE_EXTERNAL_EXPORT')then coalesce((private.dsr_file_source_state_v1(private.dsr_manifest_output_source_v1((context->>'package_id')::uuid,value->>'id'))->>'ready')::boolean,false)else false end,'acknowledged',exists(select 1 from private.dsr_response_file_ack_v1 a where a.response_id=p_response_id and a.entry_id=value->>'id'and a.subject_user_id=auth.uid()and a.response_sha256=context->>'response_sha256'and a.file_manifest_hash=context->>'file_manifest_hash'and a.download_sha256=value->>'download_sha256'))entry,ordinality ord from jsonb_array_elements(context#>'{manifest,entries}')with ordinality order by ordinality limit 25 offset(p_page-1)*25)page;
 return jsonb_build_object('response_id',p_response_id,'response_sha256',context->>'response_sha256','file_manifest_hash',context->>'file_manifest_hash','complete',context#>'{manifest,complete}','entries',items,'page',p_page,'page_size',25,'total',total,'has_next',p_page::bigint*25<total);
end$$;
create function public.authorize_my_dsr_response_file_v1(p_response_id uuid,p_file_id text)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$declare context jsonb;source jsonb;state jsonb;ticket uuid;begin
 context:=private.dsr_response_file_context_v1(p_response_id,true);source:=private.dsr_manifest_output_source_v1((context->>'package_id')::uuid,p_file_id);state:=private.dsr_file_source_state_v1(source);
 if(state->>'ready')::boolean is distinct from true then raise exception'DSR_TRUSTED_FILE_BYTES_REQUIRED'using errcode='55000';end if;
 perform private.dsr_file_transfer_rate_limit_v1();
 insert into private.dsr_file_transfer_tickets_v1(kind,actor_user_id,request_id,package_id,entry_id,response_id,source_hash,payload)values('RESPONSE_FILE',auth.uid(),(context->>'request_id')::uuid,(context->>'package_id')::uuid,p_file_id,p_response_id,source->>'source_hash',state||jsonb_build_object('source_entry',source,'response_sha256',context->>'response_sha256','file_manifest_hash',context->>'file_manifest_hash'))returning id into ticket;
 return jsonb_build_object('ticket_id',ticket,'sha256',state->>'sha256','size_bytes',state->>'size_bytes','mime_type',state->>'mime_type','file_name',state->>'file_name','response_sha256',context->>'response_sha256','file_manifest_hash',context->>'file_manifest_hash');
end$$;
create function public.record_dsr_file_transfer_access_v1(p_ticket_id uuid,p_sha256 text,p_size_bytes bigint)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$declare ticket private.dsr_file_transfer_tickets_v1%rowtype;state jsonb;context jsonb;prior private.dsr_file_transfer_completions_v1%rowtype;h text;begin
 if auth.role()is distinct from'service_role'then raise exception'DSR_TRUSTED_FILE_PROCESSOR_REQUIRED'using errcode='42501';end if;
 select*into ticket from private.dsr_file_transfer_tickets_v1 where id=p_ticket_id;
 if ticket.id is null or ticket.kind='UPLOAD_COMMIT'then raise exception'DSR_FILE_TRANSFER_EXPIRED'using errcode='42501';end if;
 if ticket.expires_at<=clock_timestamp()or not private.dsr_file_transfer_actor_live_v1(ticket)then raise exception'DSR_FILE_TRANSFER_EXPIRED'using errcode='42501';end if;
 h:=private.canonical_request_hash(jsonb_build_object('sha256',p_sha256,'size_bytes',p_size_bytes));
 if ticket.kind<>'RESPONSE_FILE'and not private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN','COMPLIANCE_MANAGER'],ticket.actor_user_id)then raise exception'DSR_RESPONSE_STAFF_REQUIRED'using errcode='42501';end if;
 state:=private.dsr_file_source_state_v1(ticket.payload->'source_entry');if(state->>'ready')::boolean is distinct from true or p_sha256 is distinct from ticket.payload->>'sha256'or p_size_bytes::text is distinct from ticket.payload->>'size_bytes'then raise exception'DSR_FILE_BYTES_MISMATCH'using errcode='22000';end if;
 if ticket.kind='RESPONSE_FILE'then context:=private.dsr_response_file_context_v1(ticket.response_id,false);if context->>'subject_user_id'is distinct from ticket.actor_user_id::text or context->>'response_sha256'is distinct from ticket.payload->>'response_sha256'or context->>'file_manifest_hash'is distinct from ticket.payload->>'file_manifest_hash'then raise exception'STALE_DSR_FILE_CONTEXT'using errcode='40001';end if;end if;
 select*into prior from private.dsr_file_transfer_completions_v1 where ticket_id=ticket.id;
 if found then if prior.request_hash is distinct from h then raise exception'IDEMPOTENCY_PAYLOAD_MISMATCH'using errcode='22000';end if;return jsonb_build_object('outcome','DSR_FILE_ACCESS_RECORDED');end if;
 insert into private.dsr_file_transfer_completions_v1(ticket_id,request_hash,sha256,size_bytes)values(ticket.id,h,p_sha256,p_size_bytes);
 insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)select organization_id,ticket.actor_user_id,'USER','privacy.file.bytes_accessed','dsr_file',ticket.entry_id,ticket.id,jsonb_build_object('ticket_id',ticket.id,'response_id',ticket.response_id,'package_id',ticket.package_id,'sha256',p_sha256,'size_bytes',p_size_bytes::text),repeat('0',64)from public.data_subject_requests where id=ticket.request_id;
 return jsonb_build_object('outcome','DSR_FILE_ACCESS_RECORDED');
end$$;
create function public.acknowledge_my_dsr_response_file_v1(p_response_id uuid,p_file_id text,p_response_sha256 text,p_file_manifest_hash text,p_download_sha256 text,p_receipt_confirmed boolean)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$declare context jsonb;entry jsonb;source jsonb;begin
 context:=private.dsr_response_file_context_v1(p_response_id,true);
 if p_response_sha256 is distinct from context->>'response_sha256'or p_file_manifest_hash is distinct from context->>'file_manifest_hash'or p_receipt_confirmed is distinct from true then raise exception'STALE_DSR_FILE_CONTEXT'using errcode='40001';end if;
 select value into entry from jsonb_array_elements(context#>'{manifest,entries}')where value->>'id'=p_file_id and value->>'disposition'<>'EXCLUDE'and(value->>'ready')::boolean;
 if entry is null or entry->>'download_sha256'is distinct from p_download_sha256 then raise exception'STALE_DSR_FILE_CONTEXT'using errcode='40001';end if;
 source:=private.dsr_manifest_output_source_v1((context->>'package_id')::uuid,p_file_id);
 if not exists(select 1 from private.dsr_file_transfer_tickets_v1 t join private.dsr_file_transfer_completions_v1 c on c.ticket_id=t.id where t.kind='RESPONSE_FILE'and t.response_id=p_response_id and t.entry_id=p_file_id and t.actor_user_id=auth.uid()and c.sha256=p_download_sha256 and t.payload->>'response_sha256'=p_response_sha256 and t.payload->>'file_manifest_hash'=p_file_manifest_hash)then raise exception'DSR_EXACT_FILE_ACCESS_REQUIRED'using errcode='55000';end if;
 insert into private.dsr_response_file_ack_v1(response_id,entry_id,subject_user_id,response_sha256,file_manifest_hash,download_sha256,source_hash)values(p_response_id,p_file_id,auth.uid(),p_response_sha256,p_file_manifest_hash,p_download_sha256,entry->>'source_hash')on conflict do nothing;
 return jsonb_build_object('outcome','DSR_RESPONSE_FILE_ACKNOWLEDGED','response_id',p_response_id,'file_id',p_file_id);
end$$;
create function private.dsr_all_files_acknowledged_v1(p_response_id uuid,p_subject_user_id uuid)returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$declare context jsonb;entry jsonb;begin
 context:=private.dsr_response_file_context_v1(p_response_id,false);if context->>'subject_user_id'is distinct from p_subject_user_id::text then return false;end if;
 for entry in select value from jsonb_array_elements(context#>'{manifest,entries}')where value->>'disposition'<>'EXCLUDE'loop
  if(entry->>'ready')::boolean is distinct from true or not exists(select 1 from private.dsr_response_file_ack_v1 a where a.response_id=p_response_id and a.entry_id=entry->>'id'and a.subject_user_id=p_subject_user_id and a.response_sha256=context->>'response_sha256'and a.file_manifest_hash=context->>'file_manifest_hash'and a.download_sha256=entry->>'download_sha256'and a.source_hash=entry->>'source_hash')then return false;end if;
 end loop;return true;
exception when sqlstate'42501'or sqlstate'40001'or sqlstate'55000'then return false;
end$$;

create function public.retry_dsr_redacted_file_scan_v1(p_upload_id uuid,p_expected_result_id uuid,p_reason text)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$declare u public.dsr_redacted_file_uploads_v1%rowtype;begin
 select*into u from public.dsr_redacted_file_uploads_v1 where id=p_upload_id for update;perform private.dsr_verified_file_request_v1(u.request_id,true);
 if u.status<>'UPLOADED'or u.scan_status<>'ERROR'or u.scan_result_id is distinct from p_expected_result_id or p_expected_result_id is null then raise exception'STALE_DSR_FILE_CONTEXT'using errcode='40001';end if;
 if length(btrim(coalesce(p_reason,'')))not between 10 and 1000 then raise exception'DSR_SCAN_RETRY_REASON_REQUIRED'using errcode='22023';end if;
 -- This is an explicit reset after an operational failure, never after malware.
 insert into private.dsr_file_scan_reset_capabilities_v1(transaction_id,upload_id,actor_user_id,expected_result_id)values(txid_current(),u.id,auth.uid(),p_expected_result_id);
 update public.dsr_redacted_file_uploads_v1 set scan_status='PENDING',scan_result_id=null where id=u.id;
 delete from private.dsr_file_scan_reset_capabilities_v1 where transaction_id=txid_current()and upload_id=u.id;
 update private.dsr_redacted_file_scan_claims_v1 set attempt_count=0,lease_token=extensions.gen_random_uuid(),leased_until=clock_timestamp(),row_version=row_version+1 where upload_id=u.id;
 insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(u.organization_id,auth.uid(),'USER','privacy.file.scan_requeued','dsr_file',u.id::text,extensions.gen_random_uuid(),jsonb_build_object('previous_result_id',p_expected_result_id,'reason',btrim(p_reason)),repeat('0',64));
 return jsonb_build_object('outcome','DSR_FILE_SCAN_REQUEUED','upload_id',u.id,'scan_status','PENDING');
end$$;
create function public.cancel_dsr_redacted_file_upload_v1(p_upload_id uuid,p_reason text)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$declare u public.dsr_redacted_file_uploads_v1%rowtype;begin
 select*into u from public.dsr_redacted_file_uploads_v1 where id=p_upload_id for update;perform private.dsr_verified_file_request_v1(u.request_id,true);
 if u.actor_user_id is distinct from auth.uid()or length(btrim(coalesce(p_reason,'')))not between 10 and 1000 then raise exception'DSR_FILE_UPLOAD_DENIED'using errcode='42501';end if;
 if exists(select 1 from public.dsr_file_disposition_proposals_v1 where p_upload_id=any(output_upload_ids))then raise exception'DSR_FILE_REVIEW_ALREADY_REFERENCED'using errcode='55000';end if;
 update public.dsr_redacted_file_uploads_v1 set status='CANCELLED'where id=u.id;
 insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(u.organization_id,auth.uid(),'USER','privacy.file.preparation_cancelled','dsr_file',u.id::text,extensions.gen_random_uuid(),jsonb_build_object('reason',btrim(p_reason)),repeat('0',64));
 return jsonb_build_object('outcome','DSR_FILE_PREPARATION_CANCELLED','upload_id',u.id);
end$$;
create function private.dsr_file_proposal_json_v1(p_id uuid)returns jsonb language sql stable security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$select jsonb_build_object('id',p.id,'version',p.version,'source_hash',p.source_hash,'disposition',p.disposition,'content_hash',p.content_hash,'legal_reference',p.legal_reference,'provenance_reference',p.provenance_reference,'reason',p.reason,'created_by',p.created_by,'created_at',p.created_at,'decision',d.decision,'review_proof_hash',d.review_proof_hash,'can_decide',d.proposal_id is null and p.created_by<>auth.uid(),'outputs',coalesce((select jsonb_agg(jsonb_build_object('source_id',o->>'source_id','sha256',o->>'sha256','file_name',o->>'file_name','size_bytes',o->>'size_bytes','mime_type',o->>'mime_type')order by o->>'source_id')from jsonb_array_elements(p.output_snapshots)o),'[]'))from public.dsr_file_disposition_proposals_v1 p left join public.dsr_file_disposition_decisions_v1 d on d.proposal_id=p.id where p.id=p_id$$;
create function public.get_dsr_file_review_context_v1(p_package_id uuid,p_page integer default 1,p_upload_page integer default 1)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$declare package public.dsr_all_packages_v1%rowtype;request public.data_subject_requests%rowtype;sources jsonb;items jsonb;uploads jsonb;total integer;upload_total bigint;begin
 select*into package from public.dsr_all_packages_v1 where id=p_package_id;request:=private.dsr_verified_file_request_v1(package.request_id,false);sources:=package.snapshot_json::jsonb->'file_sources';
 if p_page is null or p_upload_page is null or p_page not between 1 and 10000 or p_upload_page not between 1 and 10000 then raise exception'INVALID_DSR_FILE_PAGE'using errcode='22023';end if;
 total:=jsonb_array_length(coalesce(sources->'entries','[]'));
 select coalesce(jsonb_agg(item order by ord),'[]')into items from(select value||jsonb_build_object('ready',coalesce((private.dsr_file_source_state_v1(value)->>'ready')::boolean,false),'latest_proposal',(select private.dsr_file_proposal_json_v1(id)from public.dsr_file_disposition_proposals_v1 where package_id=package.id and entry_id=value->>'id'order by version desc limit 1),'proposal_count',(select count(*)from public.dsr_file_disposition_proposals_v1 where package_id=package.id and entry_id=value->>'id'))item,ordinality ord from jsonb_array_elements(coalesce(sources->'entries','[]'))with ordinality order by ordinality limit 25 offset(p_page-1)*25)page;
 select count(*)into upload_total from public.dsr_redacted_file_uploads_v1 where request_id=package.request_id;
 select coalesce(jsonb_agg(item order by version desc),'[]')into uploads from(select jsonb_build_object('id',u.id,'version',u.version,'file_name',u.file_name,'mime_type',u.mime_type,'size_bytes',u.size_bytes::text,'sha256',u.expected_sha256,'status',u.status,'scan_status',u.scan_status,'scan_result_id',u.scan_result_id,'created_at',u.created_at,'actor_user_id',u.actor_user_id,'can_cancel',u.actor_user_id=auth.uid()and not exists(select 1 from public.dsr_file_disposition_proposals_v1 where u.id=any(output_upload_ids)))item,u.version from public.dsr_redacted_file_uploads_v1 u where u.request_id=package.request_id order by version desc limit 25 offset(p_upload_page-1)*25)page;
 return jsonb_build_object('package_id',package.id,'request_id',package.request_id,'cut_source_sha256',package.source_sha256,'captured_at',package.captured_at,'can_mutate',request.status='IN_REVIEW'and package.scope_version_id=(select id from public.dsr_scope_versions_v1 where request_id=package.request_id order by version desc limit 1),'coverage_complete',coalesce((sources->>'coverage_complete')::boolean,false),'uncovered_families',coalesce(sources->'uncovered_families','[]'),'entries',items,'page',p_page,'has_next',p_page::bigint*25<total,'total',total,'uploads',uploads,'upload_page',p_upload_page,'upload_has_next',p_upload_page::bigint*25<upload_total,'upload_total',upload_total,'manifest',private.dsr_all_file_manifest_v1(package.id));
end$$;
create function public.get_dsr_file_disposition_history_v1(p_package_id uuid,p_entry_id text,p_page integer default 1)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$declare package public.dsr_all_packages_v1%rowtype;items jsonb;total bigint;begin
 select*into package from public.dsr_all_packages_v1 where id=p_package_id;perform private.dsr_verified_file_request_v1(package.request_id,false);perform private.dsr_package_file_entry_v1(package.id,p_entry_id);
 if p_page is null or p_page not between 1 and 10000 then raise exception'INVALID_DSR_FILE_PAGE'using errcode='22023';end if;
 select count(*)into total from public.dsr_file_disposition_proposals_v1 where package_id=package.id and entry_id=p_entry_id;
 select coalesce(jsonb_agg(item order by version desc),'[]')into items from(select private.dsr_file_proposal_json_v1(id)item,version from public.dsr_file_disposition_proposals_v1 where package_id=package.id and entry_id=p_entry_id order by version desc limit 25 offset(p_page-1)*25)page;
 return jsonb_build_object('items',items,'page',p_page,'total',total,'has_next',p_page::bigint*25<total);
end$$;

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)values('privacy-response-files','privacy-response-files',false,10485760,array['application/pdf','image/jpeg','image/png','text/plain','application/json','text/csv','application/zip'])on conflict(id)do nothing;
do $$begin if exists(select 1 from storage.buckets where id='privacy-response-files'and public)then raise exception'DSR_FILE_BUCKET_MUST_BE_PRIVATE'using errcode='23514';end if;end$$;
create function private.dsr_file_storage_insert_v1(p_bucket text,p_path text)returns boolean language sql stable security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$select p_bucket='privacy-response-files'and coalesce(private.dsr_response_staff_v1(),false)and exists(select 1 from public.dsr_redacted_file_uploads_v1 u join public.data_subject_requests d on d.id=u.request_id where u.storage_bucket=p_bucket and u.storage_path=p_path and u.actor_user_id=auth.uid()and u.status='RESERVED'and u.expires_at>clock_timestamp()and d.verified_at is not null and d.status='IN_REVIEW')$$;
create function private.dsr_file_storage_unbound_read_v1(p_bucket text,p_path text)returns boolean language sql stable security definer set search_path=pg_catalog,public,private set timezone='UTC' as $$select p_bucket='privacy-response-files'and coalesce(private.dsr_response_staff_v1(),false)and exists(select 1 from public.dsr_redacted_file_uploads_v1 u join public.data_subject_requests d on d.id=u.request_id where u.storage_bucket=p_bucket and u.storage_path=p_path and u.actor_user_id=auth.uid()and u.status='RESERVED'and u.expires_at>clock_timestamp()and d.verified_at is not null and d.status='IN_REVIEW')$$;
create policy dsr_file_storage_insert on storage.objects for insert to authenticated with check(private.dsr_file_storage_insert_v1(bucket_id,name));
create policy dsr_file_storage_insert_boundary on storage.objects as restrictive for insert to authenticated with check(bucket_id<>'privacy-response-files'or private.dsr_file_storage_insert_v1(bucket_id,name));
create policy dsr_file_storage_unbound_read on storage.objects for select to authenticated using(private.dsr_file_storage_unbound_read_v1(bucket_id,name));
create policy dsr_file_storage_read_boundary on storage.objects as restrictive for select to authenticated using(bucket_id<>'privacy-response-files'or private.dsr_file_storage_unbound_read_v1(bucket_id,name));
create policy dsr_file_storage_anon_boundary on storage.objects as restrictive for select to anon using(bucket_id<>'privacy-response-files');
create policy dsr_file_storage_update_boundary on storage.objects as restrictive for update to authenticated using(bucket_id<>'privacy-response-files')with check(bucket_id<>'privacy-response-files');
create policy dsr_file_storage_delete_boundary on storage.objects as restrictive for delete to authenticated using(bucket_id<>'privacy-response-files');
-- Bound and historical originals are read through scoped tickets; users cannot
-- overwrite or delete their bytes while a privacy response is being reviewed.

do $$declare f record;begin
 for f in select p.oid::regprocedure signature,n.nspname schema_name,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where(n.nspname||'.'||p.proname)=any(array['private.dsr_file_source_identity_hash_v1','private.dsr_file_candidate_v1','private.dsr_all_collect_file_sources_v1','private.dsr_verified_file_request_v1','private.guard_dsr_redacted_file_upload_v1','public.reserve_dsr_redacted_file_v1','public.authorize_dsr_file_upload_commit_v1','private.dsr_file_transfer_actor_live_v1','private.dsr_file_transfer_rate_limit_v1','public.get_dsr_file_transfer_source_v1','public.commit_dsr_redacted_file_bytes_v1','public.claim_dsr_redacted_file_scan_jobs','public.complete_dsr_redacted_file_scan_job','public.fail_dsr_redacted_file_scan_job','private.dsr_file_scan_queue_metrics_v1','private.dsr_file_source_state_v1','private.dsr_redacted_file_entry_v1','private.dsr_package_file_entry_v1','private.dsr_file_reviewed_bytes_v1','private.dsr_validate_file_outputs_v1','public.propose_dsr_file_disposition_v1','public.decide_dsr_file_disposition_v1','private.dsr_file_manifest_revision_v1','private.dsr_all_file_manifest_v1','private.dsr_response_file_context_v1','private.dsr_manifest_output_source_v1','public.authorize_dsr_file_review_v1','public.get_my_dsr_response_files_v1','public.authorize_my_dsr_response_file_v1','public.record_dsr_file_transfer_access_v1','public.acknowledge_my_dsr_response_file_v1','private.dsr_all_files_acknowledged_v1','public.retry_dsr_redacted_file_scan_v1','public.cancel_dsr_redacted_file_upload_v1','private.dsr_file_proposal_json_v1','public.get_dsr_file_review_context_v1','public.get_dsr_file_disposition_history_v1','private.dsr_file_storage_insert_v1','private.dsr_file_storage_unbound_read_v1'])loop
  execute format('revoke all on function %s from public,anon,authenticated,service_role',f.signature);
  if f.schema_name='public'then execute format('grant execute on function %s to %I',f.signature,case when f.proname=any(array['claim_dsr_redacted_file_scan_jobs','commit_dsr_redacted_file_bytes_v1','complete_dsr_redacted_file_scan_job','fail_dsr_redacted_file_scan_job','get_dsr_file_transfer_source_v1','record_dsr_file_transfer_access_v1'])then'service_role'else'authenticated'end);end if;
 end loop;
end$$;
grant execute on function private.dsr_file_storage_insert_v1(text,text),private.dsr_file_storage_unbound_read_v1(text,text)to authenticated;
notify pgrst,'reload schema';
